INSERT INTO `notifications` (`id`, `title`, `slug`, `short_desc`, `full_content`, `category`, `conducting_body`, `organization_name`, `post_type`, `notification_date`, `publish_date`, `application_start_date`, `last_date_apply`, `application_last_date`, `exam_date`, `admit_card_date`, `result_date`, `last_verified_at`, `vacancies`, `age_limit`, `qualification`, `eligibility_summary`, `fee_general`, `fee_obc`, `fee_sc_st`, `official_url`, `official_website_url`, `official_notification_pdf_url`, `official_apply_url`, `pdf_path`, `featured_image`, `status`, `computed_status`, `is_featured`, `is_homepage_visible`, `seo_title`, `meta_description`, `canonical_url`, `telegram_sent`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(NULL, 'SSC CGL 2026 – Combined Graduate Level Examination for 12,256 Posts', 'ssc-cgl-2026-combined-graduate-level-examination', 'Staff Selection Commission has released the SSC CGL 2026 notification for 12,256 Group B and Group C vacancies in various Ministries, Departments and Organisations of the Government of India. Graduates can apply online at ssc.gov.in before 22 June 2026.', '<h2>SSC CGL 2026 Recruitment – Complete Overview</h2><p>The Staff Selection Commission (SSC) has officially released the much-awaited notification for the <strong>Combined Graduate Level (CGL) Examination 2026</strong>, opening up 12,256 vacancies across a wide range of prestigious Group B and Group C posts in various Ministries, Departments and Organisations of the Government of India. The notification was published on 21 May 2026 on the official website ssc.gov.in. The SSC CGL examination is widely regarded as one of the most popular and competitive recruitment examinations in the country, attracting lakhs of graduate aspirants every year who aspire to secure a stable and respectable career in the central government sector.</p><h3>About the Posts</h3><p>Through SSC CGL 2026, candidates can be recruited to numerous coveted positions including Assistant Audit Officer, Assistant Section Officer, Income Tax Inspector, Central Excise Inspector, Preventive Officer, Sub Inspector in CBI, Assistant Enforcement Officer, Divisional Accountant, Statistical Investigator, Auditor, Accountant, Senior Secretariat Assistant, Tax Assistant and Upper Division Clerk. Each post carries an attractive pay scale ranging from Pay Level 4 to Pay Level 8 as per the 7th Central Pay Commission, along with applicable allowances such as Dearness Allowance, House Rent Allowance and Transport Allowance.</p><h3>Important Dates</h3><ul><li>Notification Release Date: 21 May 2026</li><li>Online Application Start Date: 21 May 2026</li><li>Last Date to Apply Online: 22 June 2026 (up to 11:00 PM)</li><li>Last Date for Online Fee Payment: 23 June 2026</li><li>Application Correction Window: 29 June to 1 July 2026</li><li>Tier-I Computer Based Examination: August–September 2026 (Tentative)</li><li>Tier-II Examination: December 2026 (Tentative)</li></ul><h3>Eligibility & Educational Qualification</h3><p>To be eligible for SSC CGL 2026, candidates must hold a <strong>Bachelor''s Degree in any discipline</strong> from a recognized university or an equivalent qualification as on the cut-off date. However, certain specialized posts carry additional requirements. For the post of Assistant Audit Officer / Assistant Accounts Officer, a Chartered Accountant, Cost &amp; Management Accountant, Company Secretary, Masters in Commerce, MBA (Finance) or M.Com qualification is considered a desirable qualification. For Statistical Investigator Grade-II and Junior Statistical Officer, candidates must possess a Bachelor''s Degree with Statistics as one of the subjects, or at least 60% marks in Mathematics at Class 12 level.</p><h3>Age Limit & Relaxation</h3><p>The age limit varies from post to post, generally ranging between 18 to 30 years and 18 to 32 years depending on the specific position. Age relaxation is provided as per government norms: 5 years for SC/ST candidates, 3 years for OBC candidates, 10 years for Persons with Disabilities (PwD), and additional relaxation for Ex-Servicemen and departmental candidates.</p><h3>Application Fee</h3><p>The application fee is Rs. 100 for General, OBC and EWS male candidates. Women candidates of all categories, SC, ST, PwD and eligible Ex-Servicemen are completely exempted from paying the fee. Payment can be made online through BHIM UPI, Net Banking, or Visa/Mastercard/Maestro/RuPay debit and credit cards.</p><h3>Selection Process</h3><p>The selection process consists of Tier-I (Computer Based Objective Test) and Tier-II (Computer Based Test with multiple papers), followed by Document Verification and Medical Examination where applicable. Tier-I covers General Intelligence &amp; Reasoning, General Awareness, Quantitative Aptitude and English Comprehension, while Tier-II evaluates advanced mathematical abilities, reasoning, English language, general awareness, computer knowledge and data entry skills.</p><h3>How to Apply</h3><p>Interested and eligible candidates should visit the official SSC website ssc.gov.in, register on the One Time Registration (OTR) portal, fill the online application form carefully, upload scanned photograph and signature in the prescribed format, pay the application fee, and submit the form before 22 June 2026. It is strongly advised to take a printout of the completed application for future reference.</p>', 'Central Govt', 'SSC', 'Staff Selection Commission', 'notification', '2026-05-21', '2026-05-21', '2026-05-21', '2026-06-22', '2026-06-22', '2026-08-15', NULL, NULL, '2026-06-19 10:00:00', 12256, '18-32 Years (5 years relaxation for SC/ST, 3 for OBC)', 'Bachelor''s Degree in any discipline from a recognized University or equivalent. Specific posts like Statistical Investigator require degree with Statistics or 60% Maths in Class 12.', 'Candidates must hold a Graduation degree from any recognized university. For posts like Assistant Audit Officer, CA/CS/CMA/MBA is desirable. For Statistical Investigator, a degree with Statistics is mandatory.', 100.00, 100.00, 0.00, 'https://ssc.gov.in', 'https://ssc.gov.in', 'https://ssc.gov.in/notifications/cgl-2026.pdf', 'https://ssc.gov.in/portal/apply', NULL, NULL, 'active', 'ACTIVE', 1, 1, 'SSC CGL 2026 Notification – Apply Online for 12256 Posts', 'SSC CGL 2026 recruitment notification released for 12256 vacancies. Apply online at ssc.gov.in before 22 June 2026. Check eligibility, syllabus and exam pattern.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'UPSC Civil Services IAS/IPS 2026 – 933 Vacancies Notification', 'upsc-civil-services-ias-ips-2026', 'Union Public Service Commission has announced the Civil Services Examination 2026 for recruitment to IAS, IPS, IFS and other Group A and Group B All India Services with 933 vacancies. The Preliminary Examination was held on 24 May 2026 and the Main Examination is scheduled from 21 August 2026.', '<h2>UPSC Civil Services Examination 2026 – Complete Details</h2><p>The Union Public Service Commission (UPSC) released the official notification for the <strong>Civil Services Examination (CSE) 2026</strong> on 4 February 2026, inviting applications for 933 vacancies across the most prestigious administrative services of the country. The Civil Services Examination is the gateway to elite services such as the Indian Administrative Service (IAS), Indian Police Service (IPS), Indian Foreign Service (IFS), Indian Revenue Service (IRS), Indian Audit and Accounts Service, and several other Group A and Group B central services. It is considered the toughest and most coveted competitive examination in India, attracting nearly a million aspirants annually.</p><h3>About the Services</h3><p>Candidates who clear all stages of the examination are allotted services based on their rank, category and preference. The IAS officers handle district administration, policy formulation and implementation, while IPS officers lead law enforcement and internal security. IFS officers represent India in diplomatic missions abroad. These positions offer not only an attractive salary structure under Pay Level 10 and above but also unmatched job security, social prestige, and the opportunity to contribute directly to nation building and public welfare.</p><h3>Important Dates</h3><ul><li>Notification Release Date: 4 February 2026</li><li>Online Application Start Date: 4 February 2026</li><li>Last Date to Apply Online (Extended): 27 February 2026</li><li>Preliminary Examination: 24 May 2026</li><li>Main Examination Begins: 21 August 2026</li><li>Age Eligibility Cut-off Date: 1 August 2026</li></ul><h3>Eligibility & Educational Qualification</h3><p>The candidate must hold a <strong>Bachelor''s Degree in any discipline</strong> from a recognized university or possess an equivalent qualification. Candidates who are in their final year of graduation or are awaiting results are also eligible to appear in the Preliminary Examination, provided they produce proof of passing the degree before the Main Examination. Candidates who have passed professional and technical qualifications recognized by the government as equivalent to a professional and technical degree are also eligible.</p><h3>Age Limit & Number of Attempts</h3><p>The candidate must have attained 21 years and must not have crossed 32 years of age as on 1 August 2026. Age relaxation is applicable: 5 years for SC/ST, 3 years for OBC, up to 10 years for Persons with Benchmark Disabilities, and additional relaxation for Ex-Servicemen. General category candidates are allowed 6 attempts, OBC candidates 9 attempts, while SC/ST candidates can attempt until the upper age limit. A notable change in CSE 2026 restricts serving IAS/IFS officers from re-attempting the examination.</p><h3>Application Fee</h3><p>The application fee is Rs. 100 for General and OBC candidates. Female candidates, SC, ST and Persons with Benchmark Disabilities are exempted from the fee. The fee can be paid online through Net Banking, Visa/Master/RuPay debit or credit cards, or by depositing cash at any SBI branch using the system-generated pay-in-slip.</p><h3>Selection Process</h3><p>The selection comprises three successive stages. The Preliminary Examination consists of two objective papers — General Studies Paper I and the General Studies Paper II (CSAT), the latter being qualifying in nature. The Main Examination is a written descriptive test of nine papers including essay, general studies, optional subject and language papers. Candidates who qualify the Mains are called for the Personality Test (Interview) carrying 275 marks. The final merit list is prepared based on the combined marks of the Main Examination and the Interview.</p><h3>How to Apply</h3><p>Eligible candidates should visit the official UPSC website upsc.gov.in, complete the One Time Registration, fill the detailed application form, upload the photograph, signature and photo identity card, pay the requisite fee, and submit before the deadline. Applicants are advised to keep a printout of the final submitted application form.</p>', 'Central Govt', 'UPSC', 'Union Public Service Commission', 'notification', '2026-02-04', '2026-02-04', '2026-02-04', '2026-02-27', '2026-02-27', '2026-05-24', NULL, NULL, '2026-06-19 10:00:00', 933, '21-32 Years (5 years relaxation for SC/ST, 3 for OBC)', 'Bachelor''s Degree in any discipline from a recognized University or equivalent. Final year students may apply provisionally.', 'Candidates must possess a degree from any recognized university or have an equivalent qualification. Final year degree students can apply provisionally subject to producing proof of passing before the Main Examination.', 100.00, 100.00, 0.00, 'https://upsc.gov.in', 'https://upsc.gov.in', 'https://upsc.gov.in/sites/default/files/Notif-CSP-2026-Engl.pdf', 'https://upsconline.nic.in/mainmenu2.php', NULL, NULL, 'active', 'ACTIVE', 1, 1, 'UPSC Civil Services 2026 – Apply Online for IAS/IPS 933 Posts', 'UPSC Civil Services Exam 2026 notification for 933 vacancies for IAS, IPS, IFS. Prelims held 24 May 2026, Mains from 21 Aug 2026. Check eligibility and syllabus.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'IBPS PO/MT XVI 2026 – Probationary Officer Recruitment in PSU Banks', 'ibps-po-mt-xvi-2026-probationary-officer', 'Institute of Banking Personnel Selection has announced the IBPS PO/MT-XVI 2026 recruitment for Probationary Officer and Management Trainee posts across 11 participating public sector banks. Preliminary Exam is scheduled for 22-23 August 2026 and Main Exam on 4 October 2026.', '<h2>IBPS PO/MT XVI 2026 Recruitment – Complete Overview</h2><p>The Institute of Banking Personnel Selection (IBPS) has announced the Common Recruitment Process for Probationary Officers / Management Trainees, designated as <strong>CRP PO/MT-XVI</strong>, for the year 2026. This is the 16th edition of the IBPS PO examination, conducted to recruit eligible candidates for the post of Probationary Officer (PO) in 11 participating Public Sector Banks across the country. The Probationary Officer post is one of the most aspirational banking jobs in India, offering excellent career growth, attractive salary, and the opportunity to rise to senior management positions over time.</p><h3>About the Post</h3><p>A Probationary Officer typically begins as a Scale-I officer and undergoes a probation period during which they are trained in various banking operations including customer service, loan processing, credit appraisal, treasury, and branch management. The starting basic pay is around Rs. 48,480 in the revised scale, and with allowances such as Dearness Allowance, House Rent Allowance, Special Allowance and other perks, the gross monthly emoluments are substantial. Career progression leads to Assistant Manager, Manager, Senior Manager and higher executive grades.</p><h3>Important Dates</h3><ul><li>Notification Release: June 2026</li><li>Online Registration Period: June–July 2026</li><li>Preliminary Examination: 22 & 23 August 2026</li><li>Main Examination: 4 October 2026</li><li>Interview: November–December 2026 (Tentative)</li><li>Provisional Allotment: January 2027</li></ul><h3>Eligibility & Educational Qualification</h3><p>A candidate must possess a <strong>Degree (Graduation) in any discipline</strong> from a University recognized by the Government of India, or any equivalent qualification recognized as such by the Central Government. The candidate must possess a valid Mark-sheet or Degree Certificate proving that he or she is a graduate on the day of registration. Basic computer literacy is essential, and candidates must have operated and worked on computers as part of their curriculum or otherwise. Proficiency in the official language of the state or union territory for which the candidate applies (reading, writing, speaking and understanding) is desirable.</p><h3>Age Limit & Relaxation</h3><p>The candidate must be aged between 20 and 30 years as on the cut-off date specified in the notification. Upper age relaxation is available as per government norms: 5 years for SC/ST candidates, 3 years for OBC (Non-Creamy Layer) candidates, 10 years for Persons with Benchmark Disabilities (PwBD), and additional relaxation for Ex-Servicemen and candidates affected by the 1984 riots.</p><h3>Application Fee</h3><p>The application fee is approximately Rs. 850 for General, EWS and OBC candidates, while SC, ST and PwBD candidates pay a reduced fee of around Rs. 175. The fee is paid online using debit cards, credit cards, internet banking, IMPS, cash cards or mobile wallets.</p><h3>Selection Process</h3><p>The selection process consists of three phases: a Preliminary Examination (online objective test of 100 marks covering English Language, Quantitative Aptitude and Reasoning Ability), a Main Examination (objective test of 200 marks plus a descriptive English test of 25 marks covering Reasoning &amp; Computer Aptitude, General/Economy/Banking Awareness, English Language and Data Analysis &amp; Interpretation), followed by a Personal Interview. The final merit is based on the combined scores of the Main Examination and the Interview.</p><h3>How to Apply</h3><p>Candidates must visit the official IBPS website ibps.in, click on the CRP PO/MT-XVI link, register with a valid email and mobile number, fill in the application details, upload the photograph, signature, left thumb impression and handwritten declaration, pay the fee online, and submit the form before the last date.</p>', 'Bank', 'IBPS', 'Institute of Banking Personnel Selection', 'notification', '2026-06-10', '2026-06-12', '2026-06-15', '2026-07-15', '2026-07-15', '2026-08-22', NULL, NULL, '2026-06-19 10:00:00', 5208, '20-30 Years (5 years for SC/ST, 3 for OBC)', 'Bachelor''s Degree (Graduation) in any discipline from a recognized University with basic computer knowledge. Local language proficiency desirable.', 'A degree in any discipline from a recognized university with valid mark-sheet/degree on the day of registration. Computer literacy is essential and local language proficiency is desirable.', 850.00, 850.00, 175.00, 'https://ibps.in', 'https://ibps.in', 'https://ibps.in/wp-content/uploads/CRP_PO_XVI_Notification.pdf', 'https://ibpsonline.ibps.in/crppo16/', NULL, NULL, 'active', 'ACTIVE', 1, 1, 'IBPS PO 2026 Notification – Apply Online for PSU Bank PO Posts', 'IBPS PO/MT XVI 2026 recruitment for Probationary Officer posts in PSU banks. Prelims 22-23 Aug, Mains 4 Oct 2026. Graduate eligible. Apply at ibps.in.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'SSC CHSL (10+2) 2026 – Combined Higher Secondary Level for 7,500 Posts', 'ssc-chsl-2026-combined-higher-secondary-level', 'Staff Selection Commission has released the SSC CHSL 2026 notification for recruitment to Lower Division Clerk, Data Entry Operator, Postal Assistant, Sorting Assistant and Junior Secretariat Assistant posts. 12th pass candidates can apply online at ssc.gov.in.', '<h2>SSC CHSL 2026 Recruitment – Complete Overview</h2><p>The Staff Selection Commission (SSC) conducts the <strong>Combined Higher Secondary Level (10+2) Examination 2026</strong> for recruitment to a variety of clerical and data entry posts in various Ministries, Departments and Offices of the Government of India. This examination is one of the most sought-after opportunities for 12th pass candidates who wish to secure a permanent central government job with attractive pay, job security and excellent career prospects. The notification has been released on the official website ssc.gov.in with an estimated 7,500 vacancies.</p><h3>About the Posts</h3><p>Through SSC CHSL 2026, candidates are recruited to the following posts: Lower Division Clerk (LDC) / Junior Secretariat Assistant (JSA), Postal Assistant (PA) / Sorting Assistant (SA), and Data Entry Operator (DEO). LDC and JSA posts fall under Pay Level 2, Postal and Sorting Assistants under Pay Level 4, and Data Entry Operators under Pay Level 4 or 5 depending on the department. These posts involve clerical work, data entry, file management and assistance in day-to-day office administration.</p><h3>Important Dates</h3><ul><li>Notification Release Date: 16 June 2026</li><li>Online Application Start Date: 22 June 2026</li><li>Last Date to Apply Online: 22 July 2026</li><li>Last Date for Fee Payment: 23 July 2026</li><li>Tier-I Computer Based Examination: November 2026 (Tentative)</li><li>Tier-II Examination: February 2027 (Tentative)</li></ul><h3>Eligibility & Educational Qualification</h3><p>Candidates must have <strong>passed the 12th Standard or equivalent examination</strong> from a recognized Board or University. For the post of Data Entry Operator (DEO) in the Office of Comptroller and Auditor General of India (C&amp;AG), candidates must have passed 12th in the Science stream with Mathematics as a subject from a recognized Board. There is no minimum percentage requirement, but candidates must possess the qualification before the cut-off date mentioned in the notification.</p><h3>Age Limit & Relaxation</h3><p>The age limit for SSC CHSL 2026 is between 18 and 27 years. Age relaxation is provided as per government rules: 5 years for SC/ST candidates, 3 years for OBC candidates, 10 years for Persons with Disabilities (General), 13 years for PwD-OBC, 15 years for PwD-SC/ST, and additional relaxation for Ex-Servicemen and departmental candidates.</p><h3>Application Fee</h3><p>The application fee is Rs. 100 for General and OBC male candidates. Women candidates of all categories, SC, ST, PwD and eligible Ex-Servicemen are exempted from payment of the fee. The fee can be paid online via BHIM UPI, Net Banking, or debit/credit cards.</p><h3>Selection Process</h3><p>The selection process comprises Tier-I (Computer Based Objective Examination of 200 marks covering General Intelligence, General Awareness, Quantitative Aptitude and English Language) and Tier-II (a two-session Computer Based Examination covering Mathematical Abilities, Reasoning, English, General Awareness, Computer Knowledge and a Data Entry/Typing skill test). The skill test or typing test is qualifying in nature. Final selection is based on the combined performance in Tier-I and Tier-II.</p><h3>Typing & Skill Test Requirement</h3><p>For LDC/JSA, candidates must have a typing speed of 35 words per minute in English or 30 words per minute in Hindi on a computer. For DEO posts, a data entry speed of 8,000 key depressions per hour is required, tested through the entry of given passages on a computer.</p><h3>How to Apply</h3><p>Eligible candidates must register on the SSC OTR portal at ssc.gov.in, fill the online application form, upload the scanned photograph and signature, pay the fee, and submit the form before the last date. Candidates should retain a printout of the submitted application for future reference.</p>', 'Central Govt', 'SSC', 'Staff Selection Commission', 'notification', '2026-06-16', '2026-06-17', '2026-06-22', '2026-07-22', '2026-07-22', '2026-11-05', NULL, NULL, '2026-06-19 10:00:00', 7500, '18-27 Years (5 years for SC/ST, 3 for OBC)', '12th Standard (10+2) Pass from a recognized Board. For DEO in C&AG, 12th with Mathematics in Science stream required.', 'Candidates must have passed Class 12 or equivalent from a recognized Board. Typing speed of 35 WPM English / 30 WPM Hindi required for LDC. DEO requires 8000 key depressions per hour.', 100.00, 100.00, 0.00, 'https://ssc.gov.in', 'https://ssc.gov.in', 'https://ssc.gov.in/notifications/chsl-2026.pdf', 'https://ssc.gov.in/portal/apply', NULL, NULL, 'active', 'ACTIVE', 0, 1, 'SSC CHSL 2026 – Apply Online for 7500 LDC DEO PA Posts', 'SSC CHSL 2026 notification for 7500 LDC, DEO, PA/SA posts. 12th pass eligible. Apply online at ssc.gov.in from 22 June to 22 July 2026.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'RRB NTPC Undergraduate CBT-1 Admit Card 2026 – Download Hall Ticket', 'rrb-ntpc-undergraduate-cbt-1-admit-card-2026', 'Railway Recruitment Boards have released the CBT-1 admit card and Exam City Intimation Slip for the RRB NTPC Undergraduate 2026 examination (CEN 07/2025) for 3,058 posts. The Computer Based Test is being conducted from 7 May to 21 June 2026 across 200 centres.', '<h2>RRB NTPC Undergraduate CBT-1 Admit Card 2026</h2><p>The Railway Recruitment Boards (RRBs) have released the <strong>CBT-1 Admit Card (e-Call Letter)</strong> for the RRB NTPC Undergraduate Level 2026 examination conducted under Centralised Employment Notice (CEN) No. 07/2025. This recruitment drive aims to fill 3,058 Undergraduate-level Non-Technical Popular Categories posts in Indian Railways, including Junior Clerk cum Typist, Accounts Clerk cum Typist, Trains Clerk and Commercial cum Ticket Clerk. Candidates who applied for these posts can now download their admit cards from the official regional RRB websites and the main portal rrbcdg.gov.in.</p><h3>Exam Schedule & Centres</h3><p>The RRB NTPC Undergraduate CBT-1 examination is being conducted on 7, 8 and 9 May 2026 and on 13, 14, 16, 17, 18, 19, 20 and 21 June 2026 across approximately 200 examination centres throughout the country. The examination is held in three shifts each day: the first shift from 9:00 AM to 10:30 AM, the second shift from 12:45 PM to 2:15 PM, and the third shift from 4:30 PM to 6:00 PM. Candidates must report to the centre well in advance as gates close strictly before the reporting deadline.</p><h3>Exam City Intimation Slip</h3><p>Before the release of the admit card, the RRBs publish the <strong>Exam City and Date Intimation Slip</strong> approximately 10 days prior to the examination. This slip informs candidates about their allotted examination city, date and shift, enabling them to make travel and accommodation arrangements. The SC/ST candidates can also download their free travel authority (travel pass) along with the city intimation slip.</p><h3>How to Download the Admit Card</h3><ol><li>Visit the official RRB regional website or rrbcdg.gov.in.</li><li>Click on the link for CEN 07/2025 CBT-1 e-Call Letter.</li><li>Log in using your Registration Number and Date of Birth or password.</li><li>The admit card will be displayed on the screen with your photograph, exam venue, date, shift and reporting time.</li><li>Download and take a clear printout on A4 size paper.</li></ol><h3>Documents to Carry</h3><p>Candidates must carry a printed copy of the admit card along with one original valid photo identity proof such as Aadhaar Card, PAN Card, Voter ID, Driving Licence, or Passport. A recent passport-size colour photograph (same as uploaded during application) must also be carried. Candidates with disabilities availing scribe facility must carry the relevant certificates.</p><h3>Important Instructions</h3><p>Candidates should reach the examination centre at least 60 minutes before the commencement of the test for biometric verification, frisking and document checks. Electronic gadgets including mobile phones, calculators, smartwatches, Bluetooth devices and study material are strictly prohibited inside the examination hall. Candidates must verify all details printed on the admit card and immediately contact the concerned RRB in case of any discrepancy in name, photograph, category or examination details.</p><h3>Exam Pattern</h3><p>The CBT-1 is a screening test of 90 minutes (120 minutes for PwBD candidates with scribe) consisting of 100 objective-type multiple choice questions carrying 100 marks. The question distribution is General Awareness (40 questions), Mathematics (30 questions) and General Intelligence &amp; Reasoning (30 questions). There is negative marking of one-third mark for each wrong answer. Normalisation of marks is applied since the examination is conducted in multiple shifts.</p>', 'Railways', 'RRB', 'Indian Railways', 'admitcard', '2026-04-25', '2026-04-27', NULL, NULL, NULL, '2026-05-07', '2026-04-27', NULL, '2026-06-19 10:00:00', 3058, '18-30 Years (5 years for SC/ST, 3 for OBC)', '12th (10+2) Stage Pass from a recognized Board or equivalent for Undergraduate level posts.', 'Candidates must have passed 12th (10+2) or its equivalent from a recognized Board. Typing proficiency required for typist posts at the document verification stage.', 500.00, 500.00, 250.00, 'https://rrbcdg.gov.in', 'https://rrbcdg.gov.in', 'https://rrbcdg.gov.in/notifications/cen-07-2025.pdf', 'https://rrbcdg.gov.in/admit-card', NULL, NULL, 'admitcard', 'ADMIT_CARD', 1, 1, 'RRB NTPC UG Admit Card 2026 – Download CBT-1 Hall Ticket', 'RRB NTPC Undergraduate CBT-1 admit card 2026 out for 3058 posts. Exam from 7 May to 21 June 2026. Download e-call letter and city slip at rrbcdg.gov.in.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'RRB NTPC Graduate CBT-1 Result 2026 – Check Scorecard & Cut Off', 'rrb-ntpc-graduate-cbt-1-result-2026', 'Railway Recruitment Boards have declared the CBT-1 result for the RRB NTPC Graduate Level 2026 examination (CEN 06/2025). Candidates who appeared in the Computer Based Test held from 16 to 27 March 2026 can check their qualifying status and scorecard at rrbcdg.gov.in.', '<h2>RRB NTPC Graduate CBT-1 Result 2026</h2><p>The Railway Recruitment Boards (RRBs) have officially declared the <strong>First Stage Computer Based Test (CBT-1) Result</strong> for the RRB NTPC Graduate Level 2026 recruitment conducted under Centralised Employment Notice (CEN) No. 06/2025. The CBT-1 examination was conducted nationwide from 16 March to 27 March 2026. Lakhs of candidates who appeared for the screening test can now check their qualifying status, marks and category-wise cut off on the official regional RRB websites as well as the central portal rrbcdg.gov.in.</p><h3>About the Recruitment</h3><p>The RRB NTPC Graduate Level recruitment covers popular posts such as Chief Commercial cum Ticket Supervisor, Station Master, Goods Train Manager, Junior Account Assistant cum Typist, and Senior Clerk cum Typist. These posts offer pay levels ranging from Level 4 to Level 6 under the 7th Central Pay Commission, with excellent allowances and railway-specific benefits. Candidates who qualify CBT-1 will be shortlisted to appear in the Second Stage Computer Based Test (CBT-2) in a ratio determined by the number of vacancies.</p><h3>How to Check the Result</h3><ol><li>Visit the official regional RRB website or rrbcdg.gov.in.</li><li>Click on the link titled CEN 06/2025 (Graduate) CBT-1 Result.</li><li>A PDF containing the roll numbers of shortlisted candidates will open.</li><li>Use Ctrl+F to search for your roll number in the list.</li><li>Separately, log in with your Registration Number and Date of Birth to view your individual scorecard with marks and normalised score.</li></ol><h3>Scorecard Details</h3><p>The individual scorecard displays the candidate''s name, roll number, registration number, category, raw marks, normalised marks, qualifying status, and the category-wise cut off marks. Since the examination was conducted in multiple shifts, the marks are normalised using the established formula to ensure fairness across different difficulty levels of question papers.</p><h3>Cut Off Marks</h3><p>The minimum qualifying percentages prescribed by the RRBs are 40% for Unreserved (UR) and EWS, 30% for OBC (Non-Creamy Layer) and SC, and 25% for ST candidates. However, the actual cut off for shortlisting to CBT-2 is generally much higher than these minimum qualifying marks and depends on the number of vacancies, number of candidates and overall difficulty of the examination. Category-wise and RRB-wise cut off marks are published along with the result.</p><h3>Next Steps for Qualified Candidates</h3><p>Candidates who have been shortlisted in CBT-1 must now prepare for the Second Stage CBT-2, which is more advanced and post-specific. CBT-2 carries 120 questions for 120 marks to be answered in 90 minutes, covering General Awareness, Mathematics and General Intelligence &amp; Reasoning. Candidates qualifying CBT-2 will proceed to the Typing Skill Test or Computer Based Aptitude Test (as applicable to the post), followed by Document Verification and Medical Examination before final appointment.</p><h3>Important Note</h3><p>Candidates are advised to download and preserve their scorecard for future reference. The RRBs do not send results through post or email; the result is available only on the official websites. Candidates should beware of fake websites and unofficial sources claiming to provide results, and rely solely on the official RRB portals for authentic information. In case of any grievance regarding the result, candidates may contact the concerned Railway Recruitment Board through the official helpdesk or registered email within the timeframe specified in the result notice.</p>', 'Railways', 'RRB', 'Indian Railways', 'result', '2026-03-16', '2026-06-10', NULL, NULL, NULL, '2026-03-16', NULL, '2026-06-10', '2026-06-19 10:00:00', NULL, '18-33 Years (5 years for SC/ST, 3 for OBC)', 'Bachelor''s Degree in any discipline from a recognized University or equivalent for Graduate level NTPC posts.', 'Candidates must hold a graduation degree from a recognized university. CBT-1 qualified candidates proceed to CBT-2, skill test and document verification.', 500.00, 500.00, 250.00, 'https://rrbcdg.gov.in', 'https://rrbcdg.gov.in', 'https://rrbcdg.gov.in/results/cen-06-2025-cbt1.pdf', 'https://rrbcdg.gov.in/result', NULL, NULL, 'result', 'RESULT', 1, 1, 'RRB NTPC Graduate CBT-1 Result 2026 – Scorecard & Cut Off', 'RRB NTPC Graduate CBT-1 result 2026 declared for CEN 06/2025. Check qualifying status, scorecard and cut off at rrbcdg.gov.in. Exam held 16-27 March 2026.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'RRB NTPC Undergraduate CBT-1 Answer Key 2026 – Raise Objections', 'rrb-ntpc-undergraduate-cbt-1-answer-key-2026', 'Railway Recruitment Boards have released the provisional answer key, question paper and candidate response sheet for the RRB NTPC Undergraduate CBT-1 2026 examination. Candidates can review answers and raise objections online at rrbcdg.gov.in by paying the prescribed fee per question.', '<h2>RRB NTPC Undergraduate CBT-1 Answer Key 2026</h2><p>The Railway Recruitment Boards (RRBs) have released the <strong>provisional Answer Key</strong> along with the question paper and the candidate''s recorded response sheet for the RRB NTPC Undergraduate Level CBT-1 2026 examination conducted under CEN No. 07/2025. The answer key facility allows every candidate who appeared in the Computer Based Test to view the question paper they attempted, their marked responses, and the answers considered correct by the Board. This transparent process helps candidates estimate their probable score and raise objections against any answer they believe to be incorrect.</p><h3>About the Answer Key Process</h3><p>After the conclusion of the CBT, the RRBs upload the question papers and provisional answer keys on a dedicated link. Candidates log in using their Registration Number and Date of Birth or password to access their personalised response sheet. The response sheet shows each question, the four options, the candidate''s chosen option, and the correct option as per the Board. This window remains open for a limited number of days, usually four to five days, during which objections can be submitted.</p><h3>How to Check the Answer Key</h3><ol><li>Visit the official regional RRB website or rrbcdg.gov.in.</li><li>Click on the link for CEN 07/2025 Question Paper, Response and Answer Key.</li><li>Log in with your Registration Number and Date of Birth/Password.</li><li>View your question-wise response and the provisional answer key.</li><li>Download a copy for your records and to prepare objections if needed.</li></ol><h3>How to Raise Objections</h3><p>If a candidate is not satisfied with any answer in the provisional answer key, an objection can be raised online through the same portal. A non-refundable fee of Rs. 50 per question (as prescribed by the Board) must be paid for each objection raised. This fee is refunded to the candidate''s bank account if the objection is found valid after expert review. Candidates must submit supporting documents or references to justify their objection. Objections sent through any other mode such as email or post are not entertained.</p><h3>Importance of Reviewing the Answer Key</h3><p>Reviewing the answer key is crucial because the final result and merit list are prepared on the basis of the final answer key, which is revised after considering all valid objections. By cross-checking responses against the provisional key, candidates can calculate their expected marks using the marking scheme of one mark per correct answer and one-third negative mark per wrong answer. This helps them gauge whether they are likely to clear the cut off and qualify for the next stage.</p><h3>Marking Scheme</h3><p>The CBT-1 carries 100 questions for 100 marks. Each correct answer is awarded one mark, while one-third of a mark is deducted for every incorrect answer. Unattempted questions carry no penalty. Since the examination is held across multiple shifts, the raw scores are subsequently normalised, and the normalised marks determine the final qualifying status of each candidate.</p><h3>After the Objection Window</h3><p>Once the objection window closes, a panel of subject experts reviews all submitted objections. Based on the expert recommendations, the Board prepares and releases the final answer key. The result is then processed using this final key, and candidates are shortlisted for the next stage according to the category-wise cut off and vacancy ratio.</p>', 'Railways', 'RRB', 'Indian Railways', 'notification', '2026-06-22', '2026-06-23', NULL, NULL, NULL, '2026-05-07', NULL, NULL, '2026-06-19 10:00:00', 3058, '18-30 Years (5 years for SC/ST, 3 for OBC)', '12th (10+2) Stage Pass from a recognized Board or equivalent for Undergraduate level posts.', 'Candidates who appeared in CBT-1 can review the answer key and raise objections. Final result is based on the revised final answer key after objection review.', 500.00, 500.00, 250.00, 'https://rrbcdg.gov.in', 'https://rrbcdg.gov.in', 'https://rrbcdg.gov.in/answer-key/cen-07-2025.pdf', 'https://rrbcdg.gov.in/answer-key', NULL, NULL, 'active', 'ANSWER_KEY', 0, 1, 'RRB NTPC UG CBT-1 Answer Key 2026 – Objection Link & Question Paper', 'RRB NTPC Undergraduate CBT-1 answer key 2026 released. Check response sheet and raise objections at Rs 50 per question on rrbcdg.gov.in within the window.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'SBI PO 2026 – Probationary Officer Recruitment in State Bank of India', 'sbi-po-2026-probationary-officer-recruitment', 'State Bank of India has released the SBI PO 2026 notification for recruitment of Probationary Officers. Graduates in any discipline can apply online at sbi.co.in. Selection is through Preliminary Exam, Main Exam, Group Exercise and Interview.', '<h2>SBI PO 2026 Recruitment – Complete Overview</h2><p>The State Bank of India (SBI), the largest public sector bank in the country, has released the official notification for recruitment to the post of <strong>Probationary Officer (PO)</strong> for the year 2026. The SBI PO examination is one of the most prestigious and competitive banking recruitment examinations in India, offering an excellent career path, attractive salary, pan-India posting opportunities and rapid professional growth. Lakhs of graduate candidates aspire to join SBI as Probationary Officers every year.</p><h3>About the Post</h3><p>A Probationary Officer in SBI is a Junior Management Grade Scale-I officer. After joining, the officer undergoes intensive training in banking operations, credit, customer relationship management and administration. The starting basic pay is around Rs. 48,480 with four advance increments, and the gross monthly compensation including Dearness Allowance, House Rent Allowance, City Compensatory Allowance and other perquisites is highly attractive. POs enjoy fast-track promotions and can rise to top executive positions such as Assistant General Manager, Deputy General Manager and beyond.</p><h3>Important Dates</h3><ul><li>Notification Release Date: 12 June 2026</li><li>Online Application Start Date: 14 June 2026</li><li>Last Date to Apply Online: 4 July 2026</li><li>Preliminary Examination: August 2026 (Tentative)</li><li>Main Examination: September 2026 (Tentative)</li><li>Group Exercise &amp; Interview: October–November 2026 (Tentative)</li></ul><h3>Eligibility & Educational Qualification</h3><p>The candidate must possess a <strong>Graduation degree in any discipline</strong> from a recognized University or any equivalent qualification recognized as such by the Central Government. Candidates in the final year or semester of their graduation are also eligible to apply provisionally, subject to producing proof of passing the graduation examination on or before the date specified in the notification. There is no minimum percentage of marks prescribed for graduation.</p><h3>Age Limit & Relaxation</h3><p>The candidate must be between 21 and 30 years of age as on the cut-off date mentioned in the notification. Upper age relaxation is provided as per government rules: 5 years for SC/ST candidates, 3 years for OBC (Non-Creamy Layer) candidates, 10 years for Persons with Benchmark Disabilities (General), and additional relaxation for Ex-Servicemen and other special categories.</p><h3>Application Fee</h3><p>The application fee is Rs. 750 for General, EWS and OBC candidates. SC, ST and PwBD candidates are exempted from payment of the fee. The fee is paid online through debit cards, credit cards, internet banking or other digital payment modes.</p><h3>Selection Process</h3><p>The selection process consists of four phases. Phase-I is the Preliminary Examination, an online objective test of 100 marks covering English Language, Quantitative Aptitude and Reasoning Ability, which is qualifying in nature. Phase-II is the Main Examination, comprising an objective test of 200 marks (Reasoning &amp; Computer Aptitude, Data Analysis &amp; Interpretation, General/Economy/Banking Awareness and English Language) and a descriptive test of 50 marks (Letter Writing and Essay). Phase-III consists of a Psychometric Test, Group Exercise and Personal Interview. The final merit is based on the combined marks of the Main Examination and Phase-III.</p><h3>How to Apply</h3><p>Eligible candidates should visit the official SBI careers portal at sbi.co.in, click on the SBI PO 2026 recruitment link, register with a valid email and mobile number, fill the online application form, upload the photograph, signature, left thumb impression and handwritten declaration in the prescribed format, pay the application fee online, and submit the form before the last date. Candidates are advised to keep a printout of the submitted application and fee receipt for future use.</p>', 'Bank', 'SBI', 'State Bank of India', 'notification', '2026-06-12', '2026-06-13', '2026-06-14', '2026-07-04', '2026-07-04', '2026-08-22', NULL, NULL, '2026-06-19 10:00:00', 600, '21-30 Years (5 years for SC/ST, 3 for OBC)', 'Graduation in any discipline from a recognized University. Final year students may apply provisionally.', 'Candidates must be graduates in any discipline from a recognized university. Final year students can apply provisionally. No minimum percentage prescribed.', 750.00, 750.00, 0.00, 'https://sbi.co.in/web/careers', 'https://sbi.co.in', 'https://sbi.co.in/documents/careers/po-2026-notification.pdf', 'https://ibpsonline.ibps.in/sbipojun26/', NULL, NULL, 'active', 'ACTIVE', 1, 1, 'SBI PO 2026 Notification – Apply Online for Probationary Officer', 'SBI PO 2026 recruitment notification out. Graduates can apply online at sbi.co.in before 4 July 2026. Check eligibility, exam pattern and selection process.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'RRB ALP 2026 – Assistant Loco Pilot Recruitment in Indian Railways', 'rrb-alp-2026-assistant-loco-pilot-recruitment', 'Railway Recruitment Boards have released the RRB Assistant Loco Pilot (ALP) 2026 notification for recruitment of Assistant Loco Pilots in various railway zones. Candidates with 10th pass and ITI in relevant trade can apply online at rrbcdg.gov.in.', '<h2>RRB ALP 2026 Recruitment – Complete Overview</h2><p>The Railway Recruitment Boards (RRBs) have released the Centralised Employment Notice for recruitment to the post of <strong>Assistant Loco Pilot (ALP)</strong> for the year 2026. The Assistant Loco Pilot is one of the most technically demanding and prestigious posts in Indian Railways, responsible for assisting the Loco Pilot in operating trains safely and efficiently. This recruitment offers candidates a stable, well-paid career in the railways along with the pride of contributing to one of the largest rail networks in the world.</p><h3>About the Post</h3><p>An Assistant Loco Pilot works in the locomotive cab alongside the Loco Pilot, monitoring signals, instruments, and the overall functioning of the engine. The post falls under Pay Level 2 of the 7th Central Pay Commission with a starting basic pay of Rs. 19,900 along with Running Allowance, Dearness Allowance, House Rent Allowance and other railway benefits. With experience and departmental examinations, an ALP is promoted to Loco Pilot (Goods), Loco Pilot (Passenger), Loco Pilot (Mail/Express) and further supervisory grades.</p><h3>Important Dates</h3><ul><li>Notification Release Date: 5 June 2026</li><li>Online Application Start Date: 10 June 2026</li><li>Last Date to Apply Online: 9 July 2026</li><li>Fee Payment Last Date: 11 July 2026</li><li>CBT-1 Examination: September–October 2026 (Tentative)</li></ul><h3>Eligibility & Educational Qualification</h3><p>Candidates must have passed <strong>Matriculation (10th) plus an ITI certificate</strong> from a recognized institution affiliated to NCVT or SCVT in a relevant trade such as Fitter, Electrician, Instrument Mechanic, Mechanic (Motor Vehicle), Wireman, Tractor Mechanic, Armature and Coil Winder, Mechanic (Radio &amp; TV), Electronics Mechanic, Mechanic (Diesel), Heat Engine, Turner, Machinist, or Refrigeration and Air Conditioning Mechanic. Alternatively, candidates with a three-year Diploma in Mechanical, Electrical, Electronics or Automobile Engineering, or a Degree in these branches from a recognized institution, are also eligible.</p><h3>Age Limit & Relaxation</h3><p>The age limit for RRB ALP 2026 is between 18 and 30 years as on the cut-off date. Age relaxation is provided as per government norms: 5 years for SC/ST candidates, 3 years for OBC (Non-Creamy Layer) candidates, 10 years for Persons with Benchmark Disabilities, and additional relaxation for Ex-Servicemen and other reserved categories.</p><h3>Application Fee</h3><p>The application fee is Rs. 500 for General and OBC candidates, of which Rs. 400 is refunded after appearing in CBT-1. For SC, ST, PwBD, Ex-Servicemen, women, minorities and economically backward candidates, the fee is Rs. 250, which is fully refunded after appearing in CBT-1. The fee is paid online or through bank channels.</p><h3>Selection Process</h3><p>The selection process consists of First Stage CBT (CBT-1), Second Stage CBT (CBT-2 with two parts), a Computer Based Aptitude Test (CBAT), Document Verification and Medical Examination. CBT-1 is a screening test covering Mathematics, General Intelligence &amp; Reasoning, General Science and General Awareness. CBT-2 is more advanced and includes a trade-specific section. The Computer Based Aptitude Test assesses psychological suitability for the safety-critical role, and candidates must secure a minimum of 42 marks in each test battery with no relaxation.</p><h3>How to Apply</h3><p>Eligible candidates must visit the official website rrbcdg.gov.in or the concerned regional RRB website, register with valid credentials, fill the online application form, upload the scanned photograph and signature, select the preferred RRB and trade, pay the application fee, and submit the form before the last date. A printout of the submitted application should be retained for future reference.</p>', 'Railways', 'RRB', 'Indian Railways', 'notification', '2026-06-05', '2026-06-06', '2026-06-10', '2026-07-09', '2026-07-09', '2026-09-20', NULL, NULL, '2026-06-19 10:00:00', 18799, '18-30 Years (5 years for SC/ST, 3 for OBC)', 'Matriculation (10th) plus ITI in relevant trade from NCVT/SCVT, OR Diploma/Degree in Mechanical/Electrical/Electronics/Automobile Engineering.', 'Candidates need 10th plus ITI in a relevant trade, or a Diploma/Degree in relevant engineering branch. CBAT clearance with minimum 42 marks per battery is mandatory.', 500.00, 500.00, 250.00, 'https://rrbcdg.gov.in', 'https://rrbcdg.gov.in', 'https://rrbcdg.gov.in/notifications/alp-2026.pdf', 'https://rrbcdg.gov.in/alp-apply', NULL, NULL, 'active', 'ACTIVE', 0, 1, 'RRB ALP 2026 – Apply Online for Assistant Loco Pilot Posts', 'RRB ALP 2026 recruitment notification out. 10th + ITI or Diploma holders can apply online at rrbcdg.gov.in before 9 July 2026. Check eligibility and exam pattern.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'SSC MTS & Havaldar 2026 Admit Card – Download Region-wise Hall Ticket', 'ssc-mts-havaldar-2026-admit-card', 'Staff Selection Commission has released the SSC MTS and Havaldar 2026 Computer Based Examination admit card. Candidates can download their region-wise hall tickets from the respective SSC regional websites and ssc.gov.in using their registration credentials.', '<h2>SSC MTS & Havaldar 2026 Admit Card</h2><p>The Staff Selection Commission (SSC) has released the <strong>admit card for the Multi Tasking (Non-Technical) Staff and Havaldar (CBIC &amp; CBN) Examination 2026</strong>. The admit card, also called the e-Admission Certificate, is a mandatory document required for entry into the examination hall. Candidates who successfully submitted their applications can now download the hall ticket from the respective SSC regional websites and the central portal ssc.gov.in. The MTS and Havaldar examination is one of the most popular recruitment tests for 10th pass candidates seeking Group C non-gazetted, non-ministerial posts in various Central Government Ministries and Departments.</p><h3>About the Examination</h3><p>The SSC MTS examination recruits Multi Tasking Staff for general office duties such as physical maintenance of records, photocopying, dak movement, and assistance in routine office work. The Havaldar posts are in the Central Board of Indirect Taxes and Customs (CBIC) and the Central Bureau of Narcotics (CBN), which involve a Physical Efficiency Test and Physical Standard Test in addition to the written examination. These posts offer Pay Level 1 of the 7th Central Pay Commission along with allowances.</p><h3>Region-wise Admit Card Release</h3><p>SSC conducts the examination through nine regional offices, namely Northern Region, North Western Region, Central Region, Eastern Region, Southern Region, Western Region, North Eastern Region, Madhya Pradesh Sub-Region and Karnataka-Kerala Region. Each regional office releases the admit card on its own website, while the exam city intimation and application status are published a few days before the admit card. Candidates must check the website of the region under which they applied.</p><h3>How to Download the Admit Card</h3><ol><li>Visit the concerned SSC regional website or ssc.gov.in.</li><li>Click on the Admit Card link and select the MTS/Havaldar 2026 examination.</li><li>Log in using your Registration Number/Roll Number and Date of Birth or password.</li><li>The admit card will appear with your photograph, exam venue, date, shift and reporting time.</li><li>Download and print the admit card on A4 size paper.</li></ol><h3>Documents to Carry</h3><p>Candidates must bring a printed copy of the admit card along with one original valid photo identity proof such as Aadhaar Card, Voter ID, PAN Card, Driving Licence or Passport. Two recent passport-size colour photographs identical to the one uploaded during application should also be carried. Failure to produce these documents will result in denial of entry to the examination centre.</p><h3>Important Instructions</h3><p>Candidates are advised to reach the examination centre at least one hour before the scheduled reporting time to complete biometric registration, frisking and document verification. Carrying of mobile phones, calculators, smartwatches, Bluetooth devices, electronic gadgets and any study material inside the examination hall is strictly prohibited. Candidates must carefully verify all details printed on the admit card and report any discrepancy to the regional office immediately.</p><h3>Examination Pattern</h3><p>The SSC MTS Computer Based Examination consists of two sessions. Session I covers Numerical and Mathematical Ability and Reasoning Ability and Problem Solving, while Session II covers General Awareness and English Language and Comprehension. Both sessions are computer based, and the marking scheme and negative marking provisions are as specified in the official notification. Candidates applying for Havaldar posts must subsequently qualify the Physical Efficiency Test and Physical Standard Test.</p>', 'Central Govt', 'SSC', 'Staff Selection Commission', 'admitcard', '2026-05-20', '2026-06-08', NULL, NULL, NULL, '2026-06-25', '2026-06-12', NULL, '2026-06-19 10:00:00', 8000, '18-25 Years (18-27 for some posts; relaxation as per rules)', '10th (Matriculation) Pass from a recognized Board or equivalent.', 'Candidates must have passed Class 10 from a recognized Board. Havaldar posts additionally require qualifying the Physical Efficiency Test and Physical Standard Test.', 100.00, 100.00, 0.00, 'https://ssc.gov.in', 'https://ssc.gov.in', 'https://ssc.gov.in/notifications/mts-2026.pdf', 'https://ssc.gov.in/admit-card', NULL, NULL, 'admitcard', 'ADMIT_CARD', 0, 1, 'SSC MTS Havaldar 2026 Admit Card – Download Hall Ticket', 'SSC MTS and Havaldar 2026 admit card released. Download region-wise hall ticket at ssc.gov.in using registration number and date of birth.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'IBPS Clerk (CRP Clerks-XV) 2026 Prelims Result – Check Scorecard', 'ibps-clerk-crp-clerks-xv-2026-prelims-result', 'Institute of Banking Personnel Selection has declared the Preliminary Examination result for IBPS Clerk (CRP Clerks-XV) 2026. Candidates can check their qualifying status and category-wise cut off on the official website ibps.in using their registration number and password.', '<h2>IBPS Clerk 2026 Preliminary Examination Result</h2><p>The Institute of Banking Personnel Selection (IBPS) has declared the <strong>Preliminary Examination Result for the Common Recruitment Process for Clerical Cadre (CRP Clerks-XV) 2026</strong>. This recruitment is conducted to fill clerical (Customer Service Associate) vacancies in 11 participating Public Sector Banks across the country. Candidates who appeared in the online preliminary examination can now check their qualifying status on the official website ibps.in. Those who qualify the preliminary stage are eligible to appear in the Main Examination, which determines the final selection.</p><h3>About the Recruitment</h3><p>The IBPS Clerk post, officially designated as Customer Service Associate, involves front-desk banking operations such as cash handling, passbook updating, customer service, account opening, and assistance in day-to-day branch activities. The post offers an attractive pay scale, job stability, and avenues for promotion to officer cadre through internal examinations. It is one of the most preferred entry-level banking jobs for graduates across India.</p><h3>How to Check the Result</h3><ol><li>Visit the official IBPS website ibps.in.</li><li>Click on the link for CRP Clerks-XV Preliminary Examination Result.</li><li>Log in with your Registration Number/Roll Number and Password/Date of Birth.</li><li>Your result status (Qualified/Not Qualified) will be displayed on the screen.</li><li>Download and save the result for future reference.</li></ol><h3>Cut Off and Scorecard</h3><p>The preliminary examination result is processed on the basis of the minimum qualifying marks decided by IBPS for each section and the overall cut off determined state-wise and category-wise. Since the preliminary examination is conducted in multiple shifts, the scores are normalised before declaring the result. The detailed scorecard showing sectional and total marks is usually released after the qualifying status, allowing candidates to understand their performance in English Language, Numerical Ability and Reasoning Ability.</p><h3>About the Preliminary Examination</h3><p>The IBPS Clerk Preliminary Examination is an online objective test of 100 marks to be completed in 60 minutes. It consists of three sections: English Language (30 questions, 30 marks), Numerical Ability (35 questions, 35 marks) and Reasoning Ability (35 questions, 35 marks). Each section has a separate sectional timing of 20 minutes. There is a penalty of one-fourth mark for each wrong answer. The preliminary examination is only a screening test and its marks are not counted in the final merit.</p><h3>Next Steps for Qualified Candidates</h3><p>Candidates who qualify the preliminary examination must prepare for the Main Examination, which is an online objective test of 200 marks covering General/Financial Awareness, General English, Reasoning Ability &amp; Computer Aptitude, and Quantitative Aptitude. The final merit list and provisional allotment of candidates to participating banks are based solely on the marks obtained in the Main Examination. There is no interview for the clerical cadre recruitment.</p><h3>Important Note</h3><p>Candidates are advised to regularly visit the official IBPS website for updates regarding the Main Examination admit card, exam date and final result. IBPS does not communicate results through post, email or SMS, and candidates should rely only on the official portal. Beware of fraudulent agents promising selection in exchange for money, as the entire selection process is merit-based and transparent.</p>', 'Bank', 'IBPS', 'Institute of Banking Personnel Selection', 'result', '2026-01-15', '2026-06-05', NULL, NULL, NULL, '2025-12-13', NULL, '2026-06-05', '2026-06-19 10:00:00', 6128, '20-28 Years (5 years for SC/ST, 3 for OBC)', 'Bachelor''s Degree in any discipline from a recognized University with computer literacy and local language proficiency.', 'Graduate candidates who appeared in the preliminary exam can check qualifying status. Qualified candidates proceed to the Main Examination which decides final merit.', 850.00, 850.00, 175.00, 'https://ibps.in', 'https://ibps.in', 'https://ibps.in/wp-content/uploads/clerk-xv-prelims-result.pdf', 'https://ibps.in/result', NULL, NULL, 'result', 'RESULT', 0, 1, 'IBPS Clerk 2026 Prelims Result – Check Scorecard & Cut Off', 'IBPS Clerk CRP Clerks-XV 2026 preliminary result declared. Check qualifying status, scorecard and cut off at ibps.in. Qualified candidates appear in Mains.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'SSC CGL 2026 Tier-I Answer Key – Download Response Sheet & Raise Objection', 'ssc-cgl-2026-tier-1-answer-key', 'Staff Selection Commission has released the tentative answer key for the SSC CGL 2026 Tier-I Computer Based Examination. Candidates can download their response sheet and submit objections online at ssc.gov.in by paying Rs. 100 per question challenged.', '<h2>SSC CGL 2026 Tier-I Answer Key</h2><p>The Staff Selection Commission (SSC) has released the <strong>tentative answer key for the Combined Graduate Level (CGL) Tier-I Examination 2026</strong> on its official website ssc.gov.in. Along with the answer key, the Commission has uploaded the question paper and the candidate''s recorded responses, allowing every candidate who appeared in the Tier-I Computer Based Examination to verify their answers and estimate their probable score. This transparent mechanism enables candidates to challenge any answer they believe to be incorrect before the final result is processed.</p><h3>About the Answer Key Facility</h3><p>The tentative answer key is made available through the candidate login on the SSC portal. Candidates can view each question along with the four options, the option they marked, and the answer treated as correct by the Commission. The response sheet also displays the question paper in the exact sequence in which it appeared during the examination. This facility remains active for a specified window, generally three to four days, during which candidates may raise objections against any question or answer.</p><h3>How to Download the Answer Key</h3><ol><li>Visit the official SSC website ssc.gov.in.</li><li>Click on the link for CGL 2026 Tier-I Answer Key/Response Sheet.</li><li>Log in using your Roll Number and Password or Registration details.</li><li>View and download your question paper, marked responses and the tentative answer key.</li><li>Save a copy for calculating your expected score and preparing objections.</li></ol><h3>How to Raise Objections</h3><p>Candidates who wish to challenge any answer can do so online during the objection window. A fee of Rs. 100 per question or answer challenged must be paid, which is refundable if the objection is upheld by the Commission''s expert committee. Candidates must provide valid justification and supporting references for each objection. Representations received after the deadline or through any mode other than the online portal will not be considered under any circumstances.</p><h3>Importance of the Answer Key</h3><p>The answer key is significant because the final result of Tier-I is prepared on the basis of the final answer key, which is published after evaluating all objections received from candidates. By comparing their marked responses with the tentative answer key, candidates can accurately estimate their score using the marking scheme of two marks for each correct answer and a deduction of 0.50 mark for each incorrect answer. This helps candidates assess their chances of qualifying for Tier-II.</p><h3>Tier-I Exam Pattern Recap</h3><p>The SSC CGL Tier-I examination is an online objective test of 200 marks consisting of 100 questions to be answered in 60 minutes. The four sections are General Intelligence and Reasoning (25 questions, 50 marks), General Awareness (25 questions, 50 marks), Quantitative Aptitude (25 questions, 50 marks) and English Comprehension (25 questions, 50 marks). Each correct answer carries 2 marks and 0.50 mark is deducted for every wrong answer.</p><h3>After the Objection Window</h3><p>Once the objection window closes, the Commission''s subject experts examine all the objections submitted by candidates. Based on their findings, a final answer key is prepared, and the Tier-I result is declared accordingly. Candidates who qualify Tier-I as per the category-wise cut off become eligible to appear in the Tier-II examination.</p>', 'Central Govt', 'SSC', 'Staff Selection Commission', 'notification', '2026-09-10', '2026-09-11', NULL, NULL, NULL, '2026-08-15', NULL, NULL, '2026-06-19 10:00:00', 12256, 'As per SSC CGL 2026 notification (18-32 years depending on post)', 'Bachelor''s Degree in any discipline from a recognized University or equivalent.', 'Candidates who appeared in CGL Tier-I can review the answer key and raise objections at Rs. 100 per question. Final result is based on the revised final answer key.', 100.00, 100.00, 0.00, 'https://ssc.gov.in', 'https://ssc.gov.in', 'https://ssc.gov.in/answer-key/cgl-2026-tier1.pdf', 'https://ssc.gov.in/answer-key', NULL, NULL, 'active', 'ANSWER_KEY', 0, 1, 'SSC CGL 2026 Tier-I Answer Key – Response Sheet & Objection Link', 'SSC CGL 2026 Tier-I answer key released at ssc.gov.in. Download response sheet and raise objections at Rs 100 per question within the objection window.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'UP Police Constable 2026 – UPPRPB Recruitment for Civil Police', 'up-police-constable-2026-upprpb-recruitment', 'Uttar Pradesh Police Recruitment and Promotion Board has announced a large-scale recruitment drive for Constable (Civil Police) posts. 12th pass candidates domiciled in Uttar Pradesh can apply online at uppbpb.gov.in. Selection includes written exam, PST, PET and DV.', '<h2>UP Police Constable 2026 Recruitment – Complete Overview</h2><p>The Uttar Pradesh Police Recruitment and Promotion Board (UPPRPB) has announced one of the largest state police recruitment drives in the country for the post of <strong>Constable (Civil Police)</strong>. This recruitment provides a tremendous opportunity for young aspirants in Uttar Pradesh to join the police force and serve the public while enjoying a stable government career, attractive pay and excellent growth prospects. Eligible male and female candidates can apply online through the official website uppbpb.gov.in.</p><h3>About the Post</h3><p>A Constable in the Uttar Pradesh Civil Police is responsible for maintaining law and order, preventing crime, assisting in investigations, managing traffic, and ensuring the safety and security of citizens. The post falls under Pay Level 3 of the pay matrix with a basic pay starting around Rs. 21,700, along with Dearness Allowance, House Rent Allowance and other state government benefits. Constables have clear avenues for promotion to Head Constable, Sub-Inspector and higher ranks through departmental examinations and seniority.</p><h3>Important Dates</h3><ul><li>Notification Release Date: 25 May 2026</li><li>Online Application Start Date: 1 June 2026</li><li>Last Date to Apply Online: 1 July 2026</li><li>Last Date for Fee Payment: 3 July 2026</li><li>Written Examination: October 2026 (Tentative)</li></ul><h3>Eligibility & Educational Qualification</h3><p>Candidates must have passed the <strong>Intermediate (10+2) examination</strong> from a Board recognized by the Government of Uttar Pradesh or an examination recognized as equivalent. Candidates appearing in the qualifying examination are generally not eligible; the qualification must be completed before the cut-off date specified in the notification. Candidates must also be domiciles of Uttar Pradesh to claim reservation and age relaxation benefits applicable to the state.</p><h3>Age Limit & Relaxation</h3><p>The age limit for male candidates is generally between 18 and 22 years, and for female candidates between 18 and 25 years, as on the cut-off date. Age relaxation of 5 years is provided to SC/ST and OBC candidates of Uttar Pradesh as per state government rules, along with additional relaxation for Ex-Servicemen and other reserved categories.</p><h3>Physical Standards</h3><p>For General/OBC/SC male candidates, the minimum height required is 168 cm, while for ST male candidates it is 160 cm. The chest measurement for general male candidates is 79-84 cm (with expansion). For General/OBC/SC female candidates, the minimum height is 152 cm, and for ST female candidates 147 cm, with a minimum weight of 40 kg. Candidates must also clear the Physical Efficiency Test, which involves a timed run of specified distance.</p><h3>Application Fee</h3><p>The application fee is approximately Rs. 400 for all categories including the online processing charges, payable through net banking, debit card, credit card or other digital modes as specified in the notification.</p><h3>Selection Process</h3><p>The selection process consists of a Written Examination (Computer Based or OMR based) covering General Knowledge, General Hindi, Numerical and Mental Ability, and Mental Aptitude/Intelligence/Reasoning. Candidates who qualify the written test undergo Document Verification and Physical Standard Test (PST), followed by the Physical Efficiency Test (PET). The final merit list is prepared on the basis of the written examination marks, subject to qualifying the PST and PET.</p><h3>How to Apply</h3><p>Eligible candidates should visit the official website uppbpb.gov.in, register with valid details, fill the online application form, upload the scanned photograph and signature, pay the application fee, and submit the form before the last date. A printout of the submitted application should be retained for future reference.</p>', 'State Govt', 'UPPRPB', 'Uttar Pradesh Police Recruitment and Promotion Board', 'notification', '2026-05-25', '2026-05-28', '2026-06-01', '2026-07-01', '2026-07-01', '2026-10-15', NULL, NULL, '2026-06-19 10:00:00', 19220, '18-22 Years (Male), 18-25 Years (Female); 5 years relaxation for reserved categories of UP', 'Intermediate (12th Pass) from a Board recognized by the Government of Uttar Pradesh. UP domicile required.', 'Candidates must have passed Class 12 from a recognized Board and be domiciles of Uttar Pradesh. Physical Standard Test and Physical Efficiency Test are mandatory.', 400.00, 400.00, 400.00, 'https://uppbpb.gov.in', 'https://uppbpb.gov.in', 'https://uppbpb.gov.in/notifications/constable-2026.pdf', 'https://uppbpb.gov.in/apply', NULL, NULL, 'active', 'ACTIVE', 1, 1, 'UP Police Constable 2026 – Apply Online at uppbpb.gov.in', 'UP Police Constable 2026 recruitment by UPPRPB. 12th pass UP domicile candidates can apply online before 1 July 2026. Check physical standards and exam pattern.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'RPSC RAS/RTS 2026 – Rajasthan State & Subordinate Services Combined Exam', 'rpsc-ras-rts-2026-state-subordinate-services', 'Rajasthan Public Service Commission has released the RAS/RTS Combined Competitive Examination 2026 notification for recruitment to State Service and Subordinate Service posts. Graduates can apply online through the SSO Rajasthan portal at rpsc.rajasthan.gov.in.', '<h2>RPSC RAS/RTS 2026 Recruitment – Complete Overview</h2><p>The Rajasthan Public Service Commission (RPSC) has released the official notification for the <strong>Rajasthan State and Subordinate Services Combined Competitive Examination (RAS/RTS) 2026</strong>. This examination is the gateway to prestigious administrative and allied posts in the Government of Rajasthan, including the Rajasthan Administrative Service (RAS), Rajasthan Police Service (RPS), Rajasthan Accounts Service, Rajasthan Taxation Service and various other State and Subordinate services. It is the most sought-after state civil services examination in Rajasthan, attracting lakhs of aspirants every year.</p><h3>About the Services</h3><p>Candidates selected through the RAS/RTS examination are appointed to Group A and Group B posts that carry significant administrative responsibility, social prestige and excellent career growth. RAS officers handle revenue administration, development work, and law and order at the sub-divisional and district levels, while RPS officers manage policing functions. The posts offer attractive pay under the state pay matrix along with allowances and benefits, and provide opportunities for promotion to the Indian Administrative Service over the course of a career.</p><h3>Important Dates</h3><ul><li>Notification Release Date: 20 May 2026</li><li>Online Application Start Date: 25 May 2026</li><li>Last Date to Apply Online: 25 June 2026</li><li>Preliminary Examination: September 2026 (Tentative)</li><li>Main Examination: January 2027 (Tentative)</li></ul><h3>Eligibility & Educational Qualification</h3><p>The candidate must hold a <strong>Bachelor''s Degree in any discipline</strong> from a university established by law in India or a qualification recognized as equivalent by the Government. Candidates in the final year of their degree are also eligible to apply, provided they pass the qualifying examination before the Main Examination. Candidates must also possess working knowledge of Hindi written in the Devanagari script and a knowledge of Rajasthani culture.</p><h3>Age Limit & Relaxation</h3><p>The candidate must be between 21 and 40 years of age as on the cut-off date prescribed in the notification. Age relaxation is provided as per Rajasthan government rules: 5 years for SC/ST/OBC/EWS candidates of Rajasthan and women of these categories, 5 years for women of the general category, and additional relaxation for Persons with Disabilities and other special categories.</p><h3>Application Fee</h3><p>The application fee is approximately Rs. 600 for General and Creamy Layer OBC candidates, and Rs. 400 for OBC (Non-Creamy Layer), EWS, SC, ST and PwD candidates of Rajasthan. The fee is paid online through the SSO Rajasthan portal using net banking, debit/credit cards or other digital payment options.</p><h3>Selection Process</h3><p>The selection process consists of three stages. The Preliminary Examination is an objective test of 200 marks (General Knowledge and General Science) used only for screening. The Main Examination is a descriptive written test of four papers covering General Studies and General Hindi, carrying 800 marks. Candidates who qualify the Main Examination are called for the Personal Interview of 100 marks. The final merit list is prepared on the basis of the combined marks of the Main Examination and the Interview.</p><h3>How to Apply</h3><p>Eligible candidates must register on the SSO Rajasthan portal, access the RPSC recruitment section, fill the RAS/RTS 2026 application form, upload the required documents and photograph, pay the application fee, and submit the form before the last date. Candidates should keep a printout of the submitted application for future use.</p>', 'State Govt', 'RPSC', 'Rajasthan Public Service Commission', 'notification', '2026-05-20', '2026-05-22', '2026-05-25', '2026-06-25', '2026-06-25', '2026-09-13', NULL, NULL, '2026-06-19 10:00:00', 905, '21-40 Years (5 years relaxation for reserved categories of Rajasthan and women)', 'Bachelor''s Degree in any discipline from a recognized University. Working knowledge of Hindi in Devanagari script and Rajasthani culture required.', 'Graduates from a recognized university are eligible. Final year students may apply provisionally. Knowledge of Hindi (Devanagari) and Rajasthani culture is mandatory.', 600.00, 400.00, 400.00, 'https://rpsc.rajasthan.gov.in', 'https://rpsc.rajasthan.gov.in', 'https://rpsc.rajasthan.gov.in/notifications/ras-2026.pdf', 'https://sso.rajasthan.gov.in', NULL, NULL, 'active', 'ACTIVE', 0, 1, 'RPSC RAS 2026 – Apply Online for Rajasthan Administrative Posts', 'RPSC RAS/RTS 2026 notification released for Rajasthan State and Subordinate Services. Graduates can apply online before 25 June 2026 via SSO Rajasthan portal.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'IBPS PO/MT XVI 2026 Prelims Admit Card – Download Call Letter', 'ibps-po-mt-xvi-2026-prelims-admit-card', 'Institute of Banking Personnel Selection has released the Preliminary Examination call letter for IBPS PO/MT XVI 2026. Candidates can download their admit card from ibps.in using their registration number and password. The Prelims is scheduled for 22 and 23 August 2026.', '<h2>IBPS PO/MT XVI 2026 Preliminary Admit Card</h2><p>The Institute of Banking Personnel Selection (IBPS) has released the <strong>Preliminary Examination Call Letter (Admit Card)</strong> for the Common Recruitment Process for Probationary Officers / Management Trainees (CRP PO/MT-XVI) 2026. Candidates who registered for the examination can now download their call letters from the official website ibps.in. The admit card is a mandatory document without which no candidate is allowed to enter the examination centre. The Preliminary Examination is scheduled to be conducted on 22 and 23 August 2026 in multiple shifts across various centres.</p><h3>About the Examination</h3><p>The IBPS PO recruitment fills Probationary Officer vacancies in 11 participating Public Sector Banks. The Preliminary Examination is the first stage of the selection process and serves as a screening test. Candidates who qualify the Preliminary Examination as per the cut off decided by IBPS are eligible to appear in the Main Examination, which is followed by an interview. The combined performance in the Main Examination and interview determines the final allotment.</p><h3>Pre-Examination Training Call Letter</h3><p>Before the main admit card, IBPS releases a separate call letter for Pre-Examination Training (PET) for candidates belonging to SC, ST, OBC, Minority Communities, Ex-Servicemen and Persons with Benchmark Disabilities who opted for it during registration. The training is provided free of cost to help candidates from these categories prepare effectively for the examination.</p><h3>How to Download the Admit Card</h3><ol><li>Visit the official IBPS website ibps.in.</li><li>Click on the CRP PO/MT-XVI Preliminary Call Letter download link.</li><li>Enter your Registration Number/Roll Number and Password/Date of Birth.</li><li>The call letter will be displayed with your photograph, exam centre, date, shift and reporting time.</li><li>Download and take a clear printout on A4 size paper.</li></ol><h3>Documents to Carry</h3><p>Candidates must carry the printed call letter along with a photocopy of the photo identity proof whose details were entered during registration, and the same original photo identity proof such as PAN Card, Passport, Driving Licence, Voter ID, Aadhaar Card or a valid recent identity document. A recent passport-size photograph identical to the one uploaded must be affixed and carried as instructed.</p><h3>Important Instructions</h3><p>Candidates should report to the examination venue at the reporting time mentioned on the call letter, which is well before the gate closing time. Late entry is not permitted under any circumstances. Mobile phones, calculators, smartwatches, electronic devices and any printed or written material are strictly prohibited inside the examination hall. Biometric verification of thumb impression and photograph capture is conducted at the centre and may be repeated at subsequent stages.</p><h3>Examination Pattern</h3><p>The Preliminary Examination is an online objective test of 100 marks to be completed in a composite time of 60 minutes. It comprises three sections: English Language (30 questions, 30 marks, 20 minutes), Quantitative Aptitude (35 questions, 35 marks, 20 minutes) and Reasoning Ability (35 questions, 35 marks, 20 minutes). There is a penalty of one-fourth mark for each wrong answer. Candidates must qualify each section as well as the overall cut off to be shortlisted for the Main Examination.</p>', 'Bank', 'IBPS', 'Institute of Banking Personnel Selection', 'admitcard', '2026-08-10', '2026-08-12', NULL, NULL, NULL, '2026-08-22', '2026-08-12', NULL, '2026-06-19 10:00:00', 5208, '20-30 Years (5 years for SC/ST, 3 for OBC)', 'Bachelor''s Degree in any discipline from a recognized University with basic computer knowledge.', 'Graduate candidates who registered for IBPS PO can download the prelims call letter. Qualifying the prelims is required to appear in the Main Examination.', 850.00, 850.00, 175.00, 'https://ibps.in', 'https://ibps.in', 'https://ibps.in/wp-content/uploads/crp-po-xvi-prelims-callletter.pdf', 'https://ibps.in/admit-card', NULL, NULL, 'admitcard', 'ADMIT_CARD', 0, 1, 'IBPS PO 2026 Prelims Admit Card – Download Call Letter at ibps.in', 'IBPS PO/MT XVI 2026 preliminary admit card released. Download call letter at ibps.in. Prelims on 22-23 August 2026. Check exam pattern and instructions.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'UPSC Civil Services Prelims 2026 Result – Check Roll Number List', 'upsc-civil-services-prelims-2026-result', 'Union Public Service Commission has declared the Civil Services Preliminary Examination 2026 result. Candidates who appeared in the Prelims held on 24 May 2026 can check their roll numbers in the qualified list at upsc.gov.in to proceed to the Main Examination.', '<h2>UPSC Civil Services Prelims 2026 Result</h2><p>The Union Public Service Commission (UPSC) has declared the result of the <strong>Civil Services Preliminary Examination 2026</strong>, which was conducted on 24 May 2026 across various centres in the country. The Preliminary Examination is the first screening stage of the prestigious Civil Services Examination, which selects candidates for the Indian Administrative Service, Indian Police Service, Indian Foreign Service and other Group A and Group B central services. Candidates can check whether their roll number appears in the list of qualified candidates on the official website upsc.gov.in.</p><h3>About the Result</h3><p>The Preliminary Examination result is published in the form of a PDF document containing the roll numbers of candidates who have qualified for the next stage, namely the Civil Services Main Examination. The result does not disclose marks at this stage; marks of the Preliminary Examination are released only after the conclusion of the entire examination process. Qualifying the Preliminary Examination is mandatory to be eligible to write the Main Examination, although the Prelims marks are not added to the final merit.</p><h3>How to Check the Result</h3><ol><li>Visit the official UPSC website upsc.gov.in.</li><li>Navigate to the What''s New or Examination Results section.</li><li>Click on the link for Civil Services (Preliminary) Examination 2026 Result.</li><li>A PDF with the qualified roll numbers will open.</li><li>Use Ctrl+F to search for your roll number in the list.</li></ol><h3>Next Steps for Qualified Candidates</h3><p>Candidates who qualify the Preliminary Examination must fill the Detailed Application Form (DAF-I) for the Main Examination within the timeline specified by the Commission. In the DAF, candidates provide details of their educational qualifications, work experience, service preferences and cadre preferences. The Main Examination is a written descriptive test of nine papers, including an essay paper, four General Studies papers, two optional subject papers and two qualifying language papers. It is significantly more demanding than the Preliminary stage and requires comprehensive preparation.</p><h3>About the Preliminary Examination</h3><p>The Civil Services Preliminary Examination consists of two papers, each of two hours duration. General Studies Paper I carries 200 marks and tests current affairs, history, geography, polity, economy, environment and science. General Studies Paper II, known as the Civil Services Aptitude Test (CSAT), also carries 200 marks and is qualifying in nature, requiring a minimum of 33 percent. Only the marks of General Studies Paper I are used to determine the Preliminary cut off for shortlisting candidates for the Main Examination.</p><h3>Important Note</h3><p>Candidates are strongly advised to begin their Main Examination preparation immediately after qualifying the Prelims, as the time gap between the Prelims result and the Main Examination is limited. They should regularly monitor the official UPSC website for the DAF-I submission window, Main Examination admit card and other important notices. The Commission communicates exclusively through its official website and the e-Admit Card system, and candidates should not rely on unofficial sources for result-related information. Candidates are also advised to retain a copy of the qualified list and to keep their photograph, signature and educational certificates ready in the prescribed format, as these will be required while filling the Detailed Application Form for the Main Examination within the stipulated deadline.</p>', 'Central Govt', 'UPSC', 'Union Public Service Commission', 'result', '2026-02-04', '2026-06-13', NULL, NULL, NULL, '2026-05-24', NULL, '2026-06-13', '2026-06-19 10:00:00', 933, '21-32 Years (5 years relaxation for SC/ST, 3 for OBC)', 'Bachelor''s Degree in any discipline from a recognized University or equivalent.', 'Candidates who qualify the Preliminary Examination proceed to fill DAF-I and appear in the Main Examination. Prelims marks are not counted in the final merit.', 100.00, 100.00, 0.00, 'https://upsc.gov.in', 'https://upsc.gov.in', 'https://upsc.gov.in/sites/default/files/CSP-2026-Result.pdf', 'https://upsc.gov.in/examinations/results', NULL, NULL, 'result', 'RESULT', 1, 1, 'UPSC Prelims 2026 Result Out – Check Qualified Roll Numbers', 'UPSC Civil Services Prelims 2026 result declared at upsc.gov.in. Check qualified roll numbers for the Main Examination. Prelims held on 24 May 2026.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'SSC GD Constable 2026 Result – Check Final Merit & Cut Off Marks', 'ssc-gd-constable-2026-result', 'Staff Selection Commission has declared the SSC GD Constable 2026 result for recruitment to constable posts in BSF, CRPF, CISF, ITBP, SSB, AR, SSF and NCB. Candidates can check their marks and category-wise cut off at ssc.gov.in.', '<h2>SSC GD Constable 2026 Result</h2><p>The Staff Selection Commission (SSC) has declared the result of the <strong>Constable (General Duty) Examination 2026</strong> conducted for recruitment to Constable (GD) posts in the Central Armed Police Forces (CAPFs) such as BSF, CRPF, CISF, ITBP, SSB, Assam Rifles, the Secretariat Security Force (SSF) and the Narcotics Control Bureau (NCB). Lakhs of candidates appeared in the Computer Based Examination, and those who qualified can now check their result, marks and category-wise cut off on the official website ssc.gov.in.</p><h3>About the Recruitment</h3><p>The SSC GD Constable recruitment is one of the largest uniformed-force recruitments in the country, offering 10th pass candidates an opportunity to serve in the nation''s premier security forces. The post carries Pay Level 3 of the 7th Central Pay Commission along with allowances and benefits specific to the force. Constables play a vital role in border security, internal security, anti-insurgency operations, and the protection of vital installations.</p><h3>How to Check the Result</h3><ol><li>Visit the official SSC website ssc.gov.in.</li><li>Click on the Result tab and select the Constable GD 2026 result link.</li><li>A PDF containing the roll numbers of qualified candidates will open.</li><li>Search for your roll number using Ctrl+F.</li><li>Log in to the candidate portal to view your detailed marks and scorecard.</li></ol><h3>Cut Off Marks</h3><p>The result is processed on the basis of category-wise and force-wise cut off marks, which depend on the number of vacancies, the number of candidates and the difficulty level of the examination. Cut off marks are published separately for each category, namely UR, EWS, OBC, SC and ST, and also account for the various CAPFs and states. Since the examination is conducted in multiple shifts, normalised marks are used to prepare the result.</p><h3>Next Steps for Qualified Candidates</h3><p>Candidates who qualify the Computer Based Examination are called for the Physical Efficiency Test (PET) and Physical Standard Test (PST), where height, chest and running parameters are verified. Candidates who clear the PET/PST proceed to Detailed Medical Examination (DME). Final selection and force allocation are based on the merit in the Computer Based Examination, subject to qualifying the PET, PST and medical standards.</p><h3>Examination Pattern Recap</h3><p>The SSC GD Constable Computer Based Examination consists of 80 questions for 160 marks, to be completed in 60 minutes. The four sections are General Intelligence &amp; Reasoning, General Knowledge &amp; General Awareness, Elementary Mathematics, and English/Hindi, each carrying 40 marks. Each correct answer is awarded 2 marks, and there is a negative marking of 0.50 mark for each incorrect answer.</p><h3>Important Note</h3><p>Candidates should download and preserve their scorecard and the PET/PST admit card, which is released subsequently. SSC publishes results and notices exclusively on its official website, and candidates must avoid relying on unofficial or fraudulent sources. Any grievance regarding the result can be addressed to the Commission through the prescribed channel within the stipulated time. Candidates who qualify should immediately begin preparing for the Physical Efficiency and Physical Standard Tests, maintain their fitness levels, and ensure that all original documents including the matriculation certificate, category certificate, domicile certificate and recent photographs are readily available for verification at the next stage of the recruitment process.</p>', 'Central Govt', 'SSC', 'Staff Selection Commission', 'result', '2025-08-01', '2026-06-09', NULL, NULL, NULL, '2026-02-15', NULL, '2026-06-09', '2026-06-19 10:00:00', 39481, '18-23 Years (5 years for SC/ST, 3 for OBC)', '10th (Matriculation) Pass from a recognized Board or equivalent.', 'Candidates who qualify the Computer Based Examination proceed to PET, PST and Detailed Medical Examination. Final merit is based on CBE marks.', 100.00, 100.00, 0.00, 'https://ssc.gov.in', 'https://ssc.gov.in', 'https://ssc.gov.in/results/gd-constable-2026.pdf', 'https://ssc.gov.in/result', NULL, NULL, 'result', 'RESULT', 0, 1, 'SSC GD Constable 2026 Result – Check Cut Off & Merit at ssc.gov.in', 'SSC GD Constable 2026 result declared. Check marks, category-wise cut off and PET/PST schedule at ssc.gov.in for BSF, CRPF, CISF, ITBP, SSB constable posts.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'UPSSSC PET 2026 Answer Key – Download & Submit Objections Online', 'upsssc-pet-2026-answer-key', 'Uttar Pradesh Subordinate Services Selection Commission has released the Preliminary Eligibility Test (PET) 2026 answer key. Candidates can download the answer key, match their responses and raise objections online at upsssc.gov.in within the prescribed window.', '<h2>UPSSSC PET 2026 Answer Key</h2><p>The Uttar Pradesh Subordinate Services Selection Commission (UPSSSC) has released the <strong>answer key for the Preliminary Eligibility Test (PET) 2026</strong> on its official website upsssc.gov.in. The PET is a mandatory qualifying examination for all Group C recruitments conducted by UPSSSC in the state of Uttar Pradesh. Candidates who appeared in the PET can now download the answer key, compare it with their marked responses, calculate their probable score, and raise objections against any answer they find incorrect.</p><h3>About the PET Examination</h3><p>The Preliminary Eligibility Test is a common screening test introduced by UPSSSC to streamline recruitment to various Group C posts such as Lekhpal, Junior Assistant, and other subordinate services. The PET score is valid for a defined period and is used to shortlist candidates for the main examinations of specific recruitments. A higher PET score improves a candidate''s chances of being shortlisted whenever a relevant vacancy is advertised.</p><h3>How to Download the Answer Key</h3><ol><li>Visit the official UPSSSC website upsssc.gov.in.</li><li>Click on the PET 2026 Answer Key link in the notices section.</li><li>Log in using your Registration Number and Date of Birth or password.</li><li>View and download your question paper, recorded responses and the provisional answer key.</li><li>Save the document for score calculation and objection purposes.</li></ol><h3>How to Raise Objections</h3><p>Candidates who disagree with any answer in the provisional key can submit objections online during the specified window. A prescribed fee per objection is payable, which is refunded if the objection is accepted by the expert committee. Candidates must provide proper justification and authentic references to support each objection. Objections submitted after the deadline or through offline modes are not entertained.</p><h3>Importance of the Answer Key</h3><p>Reviewing the answer key allows candidates to estimate their score and gauge their relative standing before the result is declared. The final score is calculated on the basis of the final answer key, which is published after considering all valid objections. The PET 2026 examination follows the marking scheme specified in the notification, including any applicable negative marking, and the scores are normalised across shifts where the examination is conducted in more than one session.</p><h3>Examination Pattern Recap</h3><p>The UPSSSC PET is an objective-type examination consisting of 100 questions for 100 marks to be answered in two hours. It covers Indian History, the National Movement, Geography, Indian Economy, Indian Constitution and Public Administration, General Science, Elementary Arithmetic, General Hindi, General English, Logic and Reasoning, current affairs, general awareness, and the analysis of unread passages, graphs and tables. There is negative marking of one-fourth mark for each wrong answer.</p><h3>After the Objection Window</h3><p>Once the objection window closes, the Commission''s subject experts review the objections and finalise the answer key. The PET score card is then released based on the final key. Candidates should download and preserve their PET score card, as it remains valid for the prescribed period and is required for applying to subsequent Group C recruitments conducted by UPSSSC. It is advisable to verify that all personal details such as name, category, date of birth and photograph on the score card are correct, and to report any discrepancy to the Commission promptly so that it can be rectified well before the main examination of any specific recruitment is announced.</p>', 'State Govt', 'UPSSSC', 'Uttar Pradesh Subordinate Services Selection Commission', 'notification', '2026-06-15', '2026-06-16', NULL, NULL, NULL, '2026-06-07', NULL, NULL, '2026-06-19 10:00:00', NULL, '18-40 Years (relaxation as per UP government rules)', 'Class 10 (High School) Pass from a recognized Board for appearing in PET; specific posts have higher qualifications.', 'PET is a qualifying screening test for UPSSSC Group C recruitments. Candidates can review the answer key and raise objections within the prescribed window.', 185.00, 185.00, 95.00, 'https://upsssc.gov.in', 'https://upsssc.gov.in', 'https://upsssc.gov.in/answer-key/pet-2026.pdf', 'https://upsssc.gov.in/answer-key', NULL, NULL, 'active', 'ANSWER_KEY', 0, 1, 'UPSSSC PET 2026 Answer Key – Download & Raise Objection Online', 'UPSSSC PET 2026 answer key released at upsssc.gov.in. Download response sheet, calculate score and submit objections online within the window.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'RRB Group D Level-1 2026 – Track Maintainer & Helper Recruitment', 'rrb-group-d-level-1-2026-recruitment', 'Railway Recruitment Boards have released the RRB Group D (Level-1) 2026 notification for recruitment to Track Maintainer Grade-IV, Helper/Assistant, Pointsman and other Level-1 posts in various railway zones. 10th pass or ITI holders can apply online at rrbcdg.gov.in.', '<h2>RRB Group D Level-1 2026 Recruitment – Complete Overview</h2><p>The Railway Recruitment Boards (RRBs) have released the Centralised Employment Notice for recruitment to <strong>Level-1 (Group D) posts</strong> in various departments of Indian Railways for the year 2026. This recruitment is one of the most awaited opportunities for 10th pass and ITI qualified candidates across the country, offering a permanent central government job with attractive pay, job security and avenues for departmental promotion. The posts are spread across multiple railway zones and production units.</p><h3>About the Posts</h3><p>The Level-1 posts include Track Maintainer Grade-IV, Helper/Assistant in various technical departments (Electrical, Mechanical, S&amp;T, Engineering), Assistant Pointsman, and other allied posts. These posts fall under Pay Level 1 of the 7th Central Pay Commission with a starting basic pay of Rs. 18,000, along with Dearness Allowance, House Rent Allowance, Transport Allowance and other railway benefits. Group D employees form the operational backbone of the railways and have clear promotion paths to higher grades.</p><h3>Important Dates</h3><ul><li>Notification Release Date: 8 June 2026</li><li>Online Application Start Date: 12 June 2026</li><li>Last Date to Apply Online: 12 July 2026</li><li>Fee Payment Last Date: 14 July 2026</li><li>Computer Based Test (CBT): October–November 2026 (Tentative)</li></ul><h3>Eligibility & Educational Qualification</h3><p>Candidates must have passed the <strong>10th class (Matriculation)</strong> from a recognized Board, OR possess a National Apprenticeship Certificate (NAC) granted by the National Council for Vocational Training (NCVT), OR hold an ITI certificate from institutions recognized by NCVT/SCVT. This flexible eligibility makes the recruitment accessible to a large pool of candidates with basic schooling or vocational training.</p><h3>Age Limit & Relaxation</h3><p>The age limit for RRB Group D 2026 is between 18 and 36 years as on the cut-off date. Age relaxation is provided as per government norms: 5 years for SC/ST candidates, 3 years for OBC (Non-Creamy Layer) candidates, 10 years for Persons with Benchmark Disabilities, and additional relaxation for Ex-Servicemen and other reserved categories.</p><h3>Application Fee</h3><p>The application fee is Rs. 500 for General and OBC candidates, of which Rs. 400 is refunded after appearing in the CBT. For SC, ST, Ex-Servicemen, PwBD, women, minorities and economically backward candidates, the fee is Rs. 250, which is fully refunded after appearing in the CBT. The fee is paid online or through authorised bank channels.</p><h3>Selection Process</h3><p>The selection process consists of a single Computer Based Test (CBT), followed by a Physical Efficiency Test (PET), Document Verification and Medical Examination. The CBT covers Mathematics, General Intelligence &amp; Reasoning, General Science and General Awareness on Current Affairs. The Physical Efficiency Test is qualifying in nature and has separate criteria for male and female candidates, involving lifting and carrying weights and running specified distances within stipulated times.</p><h3>How to Apply</h3><p>Eligible candidates must visit the official website rrbcdg.gov.in or the concerned regional RRB website, register with valid credentials, fill the online application form, upload the scanned photograph and signature, select the preferred RRB and posts, pay the application fee, and submit the form before the last date. Candidates should keep a printout of the submitted application for future reference.</p>', 'Railways', 'RRB', 'Indian Railways', 'notification', '2026-06-08', '2026-06-09', '2026-06-12', '2026-07-12', '2026-07-12', '2026-10-20', NULL, NULL, '2026-06-19 10:00:00', 32438, '18-36 Years (5 years for SC/ST, 3 for OBC)', '10th (Matriculation) Pass from a recognized Board OR National Apprenticeship Certificate (NAC) OR ITI from NCVT/SCVT recognized institution.', 'Candidates need 10th pass, or NAC, or ITI from a recognized institution. Physical Efficiency Test is qualifying with separate criteria for male and female candidates.', 500.00, 500.00, 250.00, 'https://rrbcdg.gov.in', 'https://rrbcdg.gov.in', 'https://rrbcdg.gov.in/notifications/group-d-2026.pdf', 'https://rrbcdg.gov.in/group-d-apply', NULL, NULL, 'active', 'ACTIVE', 1, 1, 'RRB Group D 2026 – Apply Online for Level-1 Railway Posts', 'RRB Group D Level-1 2026 recruitment notification out. 10th pass or ITI holders can apply online at rrbcdg.gov.in before 12 July 2026. Check eligibility and PET details.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'Indian Army Agniveer 2026 – Agnipath Scheme Rally Recruitment', 'indian-army-agniveer-2026-agnipath-recruitment', 'Indian Army has released the Agniveer 2026 notification for recruitment under the Agnipath Scheme across categories like Agniveer General Duty, Technical, Clerk/Store Keeper Technical and Tradesmen. Candidates can apply online through the Join Indian Army portal at joinindianarmy.nic.in.', '<h2>Indian Army Agniveer 2026 Recruitment – Complete Overview</h2><p>The Indian Army has released the notification for recruitment of <strong>Agniveers under the Agnipath Scheme 2026</strong>. The Agnipath Scheme is a transformative recruitment model for enrolling soldiers into the Indian Army for a period of four years, offering young Indians the opportunity to serve the nation, develop discipline and skills, and receive an attractive financial package. The recruitment is conducted across multiple categories to suit varying educational qualifications and aptitudes.</p><h3>About the Categories</h3><p>The Agniveer recruitment is conducted in categories such as Agniveer General Duty (GD), Agniveer Technical, Agniveer Clerk/Store Keeper Technical, and Agniveer Tradesmen (10th and 8th pass). Selected Agniveers undergo rigorous military training and serve in various arms and services of the Army. On completion of the four-year engagement, a certain percentage of Agniveers are retained in the regular cadre based on merit, while others receive a generous Seva Nidhi package and skill certificates to support their future careers.</p><h3>Important Dates</h3><ul><li>Notification Release Date: 1 June 2026</li><li>Online Registration Start Date: 5 June 2026</li><li>Last Date to Apply Online: 5 July 2026</li><li>Online Common Entrance Examination: September 2026 (Tentative)</li><li>Recruitment Rally (Physical &amp; Medical): As scheduled zone-wise</li></ul><h3>Eligibility & Educational Qualification</h3><p>The educational qualification varies by category. For Agniveer General Duty, candidates must have passed Class 10 (Matriculation) with at least 45 percent marks in aggregate and 33 percent in each subject. For Agniveer Technical, candidates must have passed Class 12 in the Science stream with Physics, Chemistry, Mathematics and English with the prescribed minimum marks. For Agniveer Clerk/Store Keeper Technical, candidates must have passed Class 12 in any stream with the required aggregate and subject-wise marks. For Agniveer Tradesmen, the qualification is Class 10 or Class 8 depending on the trade.</p><h3>Age Limit</h3><p>The age limit for Agniveer recruitment is between 17.5 and 21 years as on the cut-off date specified in the notification. The recruitment is open to candidates who meet the prescribed age band, and there is no upper-age relaxation beyond the band as the engagement is specific to the Agnipath Scheme.</p><h3>Physical Standards</h3><p>Candidates must meet the physical standards prescribed for their region and category, including minimum height, weight and chest measurements. The Physical Fitness Test includes a 1.6 km run, pull-ups (beam), a balance test and a 9-feet ditch jump, each carrying specified marks or qualifying criteria. Candidates must also clear a thorough medical examination conducted by the military medical board.</p><h3>Selection Process</h3><p>The selection process consists of an Online Common Entrance Examination (CEE), followed by a Recruitment Rally comprising the Physical Fitness Test and Physical Measurement Test, and finally a Medical Examination. The merit is prepared on the basis of performance in the CEE and the physical tests, subject to meeting medical standards. Document verification is carried out at the rally site.</p><h3>How to Apply</h3><p>Eligible candidates must register on the official Join Indian Army portal at joinindianarmy.nic.in, fill the online application form, select the category and rally location, upload the required documents, and submit the application before the last date. Candidates should carry all original documents to the recruitment rally as instructed.</p>', 'Defence', 'Indian Army', 'Indian Army', 'notification', '2026-06-01', '2026-06-02', '2026-06-05', '2026-07-05', '2026-07-05', '2026-09-10', NULL, NULL, '2026-06-19 10:00:00', 25000, '17.5-21 Years as on the cut-off date', 'Varies by category: 10th pass with 45% for Agniveer GD; 12th Science (PCM) for Agniveer Technical; 12th any stream for Clerk/SKT; 10th/8th for Tradesmen.', 'Educational qualification varies by Agniveer category. Candidates must clear the Online Common Entrance Exam, Physical Fitness Test, Measurement Test and Medical Examination.', 250.00, 250.00, 250.00, 'https://joinindianarmy.nic.in', 'https://joinindianarmy.nic.in', 'https://joinindianarmy.nic.in/notifications/agniveer-2026.pdf', 'https://joinindianarmy.nic.in', NULL, NULL, 'active', 'ACTIVE', 1, 1, 'Indian Army Agniveer 2026 – Apply Online under Agnipath Scheme', 'Indian Army Agniveer 2026 recruitment under Agnipath Scheme. Apply online at joinindianarmy.nic.in before 5 July 2026. Check category-wise eligibility and physical standards.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'NTA NEET UG 2026 Admit Card – Download City Slip & Hall Ticket', 'nta-neet-ug-2026-admit-card', 'National Testing Agency has released the NEET UG 2026 admit card for the National Eligibility cum Entrance Test for undergraduate medical admissions. Candidates can download the city intimation slip and hall ticket from neet.nta.nic.in using their application number and password.', '<h2>NTA NEET UG 2026 Admit Card</h2><p>The National Testing Agency (NTA) has released the <strong>admit card for the National Eligibility cum Entrance Test (NEET) UG 2026</strong>, the single national-level entrance examination for admission to MBBS, BDS, AYUSH, veterinary and other undergraduate medical and allied courses across India. Candidates who registered for the examination can download their admit card from the official website neet.nta.nic.in. The admit card is an essential document required for entry into the examination centre and contains critical details about the exam venue, date, timing and reporting instructions.</p><h3>About the Examination</h3><p>NEET UG is conducted in pen-and-paper mode and is the qualifying examination for admission to nearly all medical colleges in the country, including government and private institutions, as well as for All India Quota and State Quota seats. The examination assesses candidates in Physics, Chemistry and Biology (Botany and Zoology) based on the Class 11 and Class 12 syllabus. It is one of the largest entrance examinations in the world by number of candidates.</p><h3>Exam City Intimation Slip</h3><p>Prior to the release of the admit card, NTA publishes the Exam City Intimation Slip, which informs candidates of the city allotted for their examination. This advance intimation helps candidates plan their travel and accommodation. The city slip is not the admit card; the actual admit card with the specific centre address is released a few days before the examination.</p><h3>How to Download the Admit Card</h3><ol><li>Visit the official NEET website neet.nta.nic.in.</li><li>Click on the NEET UG 2026 Admit Card download link.</li><li>Enter your Application Number, Date of Birth and security pin.</li><li>The admit card will be displayed with your photograph, exam centre, date, timing and reporting time.</li><li>Download and print the admit card on A4 size paper, and read all instructions carefully.</li></ol><h3>Documents to Carry</h3><p>Candidates must carry the printed admit card with the passport-size photograph affixed in the designated space, a valid original photo identity proof such as Aadhaar Card, and a passport-size photograph identical to the one uploaded during registration. A simple transparent water bottle and personal hand sanitizer are permitted as per the dress code and instructions. PwD candidates availing a scribe must carry the relevant certificate.</p><h3>Important Instructions & Dress Code</h3><p>Candidates must adhere strictly to the NTA dress code, which prohibits clothing with large buttons, brooches, and footwear such as shoes; light slippers or sandals are advised. Items such as mobile phones, calculators, electronic gadgets, study material, watches and metallic items are strictly prohibited inside the examination hall. Candidates should report at the centre well before the gate closing time, as late entry is not permitted under any circumstances.</p><h3>Examination Pattern</h3><p>NEET UG consists of 180 questions to be answered in a duration of 200 minutes. The paper covers Physics, Chemistry, Botany and Zoology, with each correct answer carrying 4 marks and a deduction of 1 mark for each incorrect answer. The total maximum marks are 720. Candidates must qualify by securing at least the minimum percentile prescribed for their category to be eligible for counselling.</p>', 'Admission', 'NTA', 'National Testing Agency', 'admitcard', '2026-03-01', '2026-04-25', NULL, NULL, NULL, '2026-05-03', '2026-04-25', NULL, '2026-06-19 10:00:00', NULL, '17 Years minimum as on 31 December of admission year (no upper age limit)', '10+2 with Physics, Chemistry, Biology/Biotechnology and English with minimum qualifying marks from a recognized Board.', 'Candidates must have passed 10+2 with Physics, Chemistry and Biology with the prescribed minimum marks. Admit card is mandatory for entry to the examination centre.', 1700.00, 1700.00, 1000.00, 'https://neet.nta.nic.in', 'https://nta.ac.in', 'https://neet.nta.nic.in/notifications/neet-ug-2026.pdf', 'https://neet.nta.nic.in/admit-card', NULL, NULL, 'admitcard', 'ADMIT_CARD', 1, 1, 'NEET UG 2026 Admit Card – Download Hall Ticket at neet.nta.nic.in', 'NTA NEET UG 2026 admit card released. Download city slip and hall ticket at neet.nta.nic.in using application number and date of birth. Check dress code and instructions.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'SSC JE 2026 – Junior Engineer (Civil, Mechanical, Electrical) Recruitment', 'ssc-je-2026-junior-engineer-recruitment', 'Staff Selection Commission has released the SSC Junior Engineer (JE) 2026 notification for recruitment to Junior Engineer posts in Civil, Mechanical, Electrical and Quantity Surveying & Contracts disciplines in various central government departments. Diploma and Degree engineers can apply online at ssc.gov.in.', '<h2>SSC JE 2026 Recruitment – Complete Overview</h2><p>The Staff Selection Commission (SSC) has released the official notification for recruitment to the post of <strong>Junior Engineer (JE) 2026</strong> in the disciplines of Civil, Mechanical, Electrical, and Quantity Surveying &amp; Contracts. The Junior Engineer posts are available in various participating departments and organisations of the Government of India such as the Central Public Works Department (CPWD), Military Engineer Services (MES), Central Water Commission, Border Roads Organisation, Farakka Barrage Project and others. This recruitment is a prestigious opportunity for diploma and degree holders in engineering to secure a stable and well-paid technical government job.</p><h3>About the Post</h3><p>A Junior Engineer is responsible for the planning, execution, supervision and maintenance of engineering projects and works in the respective department. The post falls under Pay Level 6 of the 7th Central Pay Commission, with a pay scale of Rs. 35,400 to Rs. 1,12,400, along with Dearness Allowance, House Rent Allowance, Transport Allowance and other applicable benefits. Junior Engineers play a key role in infrastructure development and have clear avenues for promotion to Assistant Engineer and higher technical posts.</p><h3>Important Dates</h3><ul><li>Notification Release Date: 10 June 2026</li><li>Online Application Start Date: 15 June 2026</li><li>Last Date to Apply Online: 15 July 2026</li><li>Last Date for Fee Payment: 16 July 2026</li><li>Paper-I Computer Based Examination: October 2026 (Tentative)</li><li>Paper-II Examination: December 2026 (Tentative)</li></ul><h3>Eligibility & Educational Qualification</h3><p>The educational qualification varies according to the discipline and the department. For most posts, candidates must possess a <strong>Diploma or Degree in the relevant engineering branch</strong> (Civil, Mechanical or Electrical) from a recognized university or institution. For certain departments such as CPWD and MES, a three-year Diploma in the relevant engineering discipline is the minimum requirement, while some posts require a Degree along with relevant work experience. Candidates must carefully read the post-wise eligibility conditions mentioned in the official notification.</p><h3>Age Limit & Relaxation</h3><p>The age limit for SSC JE 2026 is generally up to 30 years or 32 years depending on the specific post and department. Age relaxation is provided as per government rules: 5 years for SC/ST candidates, 3 years for OBC candidates, 10 years for Persons with Disabilities, and additional relaxation for Ex-Servicemen and departmental candidates as applicable.</p><h3>Application Fee</h3><p>The application fee is Rs. 100 for General and OBC candidates. Women candidates of all categories, SC, ST, PwD and eligible Ex-Servicemen are exempted from payment of the fee. The fee is paid online through BHIM UPI, Net Banking, or debit/credit cards before the prescribed deadline.</p><h3>Selection Process</h3><p>The selection process consists of two stages. Paper-I is a Computer Based Objective Examination covering General Intelligence &amp; Reasoning, General Awareness, and General Engineering (Civil &amp; Structural, Electrical or Mechanical as per the chosen discipline). Paper-II is a more advanced Computer Based Examination focusing exclusively on the technical subject of the candidate''s engineering discipline. The final merit is prepared on the basis of the combined performance in Paper-I and Paper-II, followed by document verification.</p><h3>How to Apply</h3><p>Eligible candidates must register on the SSC One Time Registration portal at ssc.gov.in, fill the online application form for JE 2026, upload the scanned photograph and signature, select the preferred posts and departments, pay the application fee, and submit the form before the last date. Candidates should retain a printout of the submitted application for future reference.</p>', 'Central Govt', 'SSC', 'Staff Selection Commission', 'notification', '2026-06-10', '2026-06-11', '2026-06-15', '2026-07-15', '2026-07-15', '2026-10-12', NULL, NULL, '2026-06-19 10:00:00', 1340, 'Up to 30-32 Years depending on post (5 years for SC/ST, 3 for OBC)', 'Diploma or Degree in relevant Engineering discipline (Civil/Mechanical/Electrical) from a recognized institution. Some posts require relevant work experience.', 'Candidates must hold a Diploma or Degree in the relevant engineering branch. Post-wise eligibility including experience requirements is specified in the notification.', 100.00, 100.00, 0.00, 'https://ssc.gov.in', 'https://ssc.gov.in', 'https://ssc.gov.in/notifications/je-2026.pdf', 'https://ssc.gov.in/portal/apply', NULL, NULL, 'active', 'ACTIVE', 0, 1, 'SSC JE 2026 – Apply Online for Junior Engineer Posts at ssc.gov.in', 'SSC JE 2026 recruitment for Junior Engineer Civil, Mechanical, Electrical posts. Diploma/Degree engineers can apply online at ssc.gov.in before 15 July 2026.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'IBPS RRB 2026 – Officer Scale I, II, III & Office Assistant Recruitment', 'ibps-rrb-2026-officer-office-assistant-recruitment', 'Institute of Banking Personnel Selection has released the IBPS RRB 2026 (CRP RRBs-XIV) notification for recruitment of Officer Scale I, II, III and Office Assistant (Multipurpose) in Regional Rural Banks across the country. Graduates can apply online at ibps.in.', '<h2>IBPS RRB 2026 Recruitment – Complete Overview</h2><p>The Institute of Banking Personnel Selection (IBPS) has released the notification for the Common Recruitment Process for Regional Rural Banks, designated as <strong>CRP RRBs-XIV</strong>, for the year 2026. This recruitment is conducted to fill vacancies for Officer Scale I (Assistant Manager), Officer Scale II (Manager), Officer Scale III (Senior Manager) and Office Assistant (Multipurpose) in various Regional Rural Banks (RRBs) operating across the states of India. RRB jobs are highly preferred for the benefit of local posting, attractive pay and a stable banking career close to home.</p><h3>About the Posts</h3><p>Office Assistants handle clerical and customer service functions at the branch level, while Officer Scale I officers perform managerial duties in branch banking. Officer Scale II and III posts are for experienced professionals in general banking and specialist roles such as Information Technology, Chartered Accountant, Law, Treasury, Marketing and Agricultural Officer. These posts offer pay and allowances comparable to nationalised banks, along with rural and semi-urban postings that contribute to financial inclusion.</p><h3>Important Dates</h3><ul><li>Notification Release Date: 6 June 2026</li><li>Online Application Start Date: 7 June 2026</li><li>Last Date to Apply Online: 27 June 2026</li><li>Officer Scale I &amp; Office Assistant Prelims: August 2026 (Tentative)</li><li>Single/Main Examination: September–October 2026 (Tentative)</li></ul><h3>Eligibility & Educational Qualification</h3><p>For Office Assistant and Officer Scale I, candidates must possess a <strong>Bachelor''s Degree in any discipline</strong> from a recognized University. Preference is given to candidates with proficiency in the local language and knowledge of computers. For Officer Scale II General Banking Officer, a degree with a minimum of 50 percent marks along with two years of banking experience is required. For Officer Scale II specialist posts and Officer Scale III, the relevant professional qualification (such as CA, MBA, degree in IT/Law/Agriculture) along with the prescribed experience is mandatory.</p><h3>Age Limit & Relaxation</h3><p>The age limit varies by post: Office Assistant (18-28 years), Officer Scale I (18-30 years), Officer Scale II (21-32 years) and Officer Scale III (21-40 years). Age relaxation is applicable as per government norms: 5 years for SC/ST, 3 years for OBC, 10 years for PwBD, and additional relaxation for Ex-Servicemen and other eligible categories.</p><h3>Application Fee</h3><p>The application fee is approximately Rs. 850 for General, EWS and OBC candidates, and Rs. 175 for SC, ST and PwBD candidates. The fee is paid online using debit cards, credit cards, internet banking or other digital payment methods within the application window.</p><h3>Selection Process</h3><p>For Office Assistant, the selection consists of a Preliminary Examination and a Main Examination. For Officer Scale I, it consists of a Preliminary Examination, a Main Examination and an Interview. For Officer Scale II and III, selection is through a Single Examination followed by an Interview. The examinations test Reasoning, Quantitative Aptitude/Numerical Ability, General Awareness, English/Hindi Language and Computer Knowledge, with the syllabus and weightage varying by post.</p><h3>How to Apply</h3><p>Eligible candidates must visit the official IBPS website ibps.in, click on the CRP RRBs-XIV link, register with a valid email and mobile number, fill the online application form, upload the required documents, pay the fee online, and submit the application before the last date. A printout of the submitted form should be kept for future reference.</p>', 'Bank', 'IBPS', 'Institute of Banking Personnel Selection', 'notification', '2026-06-06', '2026-06-07', '2026-06-07', '2026-06-27', '2026-06-27', '2026-08-09', NULL, NULL, '2026-06-19 10:00:00', 9923, '18-40 Years depending on post (relaxation as per government norms)', 'Bachelor''s Degree in any discipline for Office Assistant and Officer Scale I. Officer Scale II/III require relevant professional qualification and experience.', 'Graduates are eligible for Office Assistant and Officer Scale I. Officer Scale II and III require relevant degree/professional qualification with prescribed banking experience.', 850.00, 850.00, 175.00, 'https://ibps.in', 'https://ibps.in', 'https://ibps.in/wp-content/uploads/crp-rrb-xiv-2026.pdf', 'https://ibps.in/rrb-apply', NULL, NULL, 'active', 'ACTIVE', 0, 1, 'IBPS RRB 2026 – Apply Online for Officer & Office Assistant Posts', 'IBPS RRB 2026 CRP RRBs-XIV notification out for Officer Scale I/II/III and Office Assistant. Graduates can apply online at ibps.in before 27 June 2026.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'SSC CHSL 2026 Tier-I Result – Check Marks & Tier-II Shortlist', 'ssc-chsl-2026-tier-1-result', 'Staff Selection Commission has declared the SSC CHSL 2026 Tier-I result. Candidates who appeared in the Combined Higher Secondary Level Tier-I Computer Based Examination can check their marks and the list of candidates shortlisted for Tier-II at ssc.gov.in.', '<h2>SSC CHSL 2026 Tier-I Result</h2><p>The Staff Selection Commission (SSC) has declared the <strong>Tier-I result for the Combined Higher Secondary Level (CHSL) Examination 2026</strong>. The Tier-I Computer Based Examination was conducted for recruitment to Lower Division Clerk, Junior Secretariat Assistant, Postal Assistant, Sorting Assistant and Data Entry Operator posts in various central government ministries and departments. Candidates who appeared in the examination can now check their result and the list of candidates shortlisted for the Tier-II examination on the official website ssc.gov.in.</p><h3>About the Result</h3><p>The Tier-I result is published as a list of roll numbers of candidates who have qualified for the next stage, namely the Tier-II examination. The Commission also releases category-wise cut off marks and individual scorecards showing the marks obtained by each candidate. Since the Tier-I examination is conducted in multiple shifts, the marks are normalised to ensure parity across different sessions before the result is processed.</p><h3>How to Check the Result</h3><ol><li>Visit the official SSC website ssc.gov.in.</li><li>Click on the Result tab and select the CHSL 2026 Tier-I result link.</li><li>A PDF containing the qualified roll numbers will open.</li><li>Search for your roll number using Ctrl+F.</li><li>Log in to the candidate portal to download your individual scorecard with marks.</li></ol><h3>Cut Off Marks</h3><p>The cut off marks are released separately for each category, namely Unreserved, EWS, OBC, SC, ST, and various sub-categories such as Ex-Servicemen and Persons with Disabilities. The cut off depends on the number of vacancies, the number of candidates, and the overall difficulty level of the examination. Candidates scoring at or above the cut off for their category are shortlisted to appear in the Tier-II examination.</p><h3>Next Steps for Qualified Candidates</h3><p>Candidates shortlisted in Tier-I must prepare for the Tier-II examination, which is a more comprehensive Computer Based Test conducted in two sessions. Tier-II evaluates Mathematical Abilities, Reasoning and General Intelligence, English Language and Comprehension, General Awareness, Computer Knowledge, and a Data Entry/Typing Skill Test. The skill test and typing test are qualifying in nature. The final merit and post allocation are based on the performance in the Tier-II examination, subject to document verification.</p><h3>Tier-I Exam Pattern Recap</h3><p>The SSC CHSL Tier-I examination is an online objective test of 200 marks consisting of 100 questions to be answered in 60 minutes. The four sections are General Intelligence, General Awareness, Quantitative Aptitude and English Language, each carrying 50 marks. Each correct answer is awarded 2 marks, and 0.50 mark is deducted for each wrong answer.</p><h3>Important Note</h3><p>Candidates are advised to download and preserve their scorecard for future reference. SSC declares results and notices exclusively on its official website, and candidates should avoid relying on unofficial or fraudulent sources. Any representation regarding the result must be made to the Commission through the prescribed channel within the time limit specified in the result notice, after which no grievance will be entertained. Candidates who have qualified should keep their educational certificates, category certificate and recent photographs ready, and should regularly check the official website for the Tier-II admit card, examination date and other important announcements related to the next stage of the recruitment.</p>', 'Central Govt', 'SSC', 'Staff Selection Commission', 'result', '2025-12-01', '2026-06-11', NULL, NULL, NULL, '2026-04-10', NULL, '2026-06-11', '2026-06-19 10:00:00', 7500, '18-27 Years (5 years for SC/ST, 3 for OBC)', '12th Standard (10+2) Pass from a recognized Board or equivalent.', 'Candidates qualifying Tier-I proceed to Tier-II which decides final merit. A typing/skill test is qualifying in nature for the relevant posts.', 100.00, 100.00, 0.00, 'https://ssc.gov.in', 'https://ssc.gov.in', 'https://ssc.gov.in/results/chsl-2026-tier1.pdf', 'https://ssc.gov.in/result', NULL, NULL, 'result', 'RESULT', 0, 1, 'SSC CHSL 2026 Tier-I Result – Check Marks & Cut Off at ssc.gov.in', 'SSC CHSL 2026 Tier-I result declared. Check marks, category-wise cut off and Tier-II shortlist at ssc.gov.in. Download scorecard using login credentials.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'CTET July 2026 Admit Card – Download CBSE Hall Ticket Online', 'ctet-july-2026-admit-card', 'Central Board of Secondary Education has released the CTET July 2026 admit card for the Central Teacher Eligibility Test. Candidates can download their hall ticket from ctet.nic.in using their application number and date of birth. The examination assesses eligibility for teaching posts in Classes I to VIII.', '<h2>CTET July 2026 Admit Card</h2><p>The Central Board of Secondary Education (CBSE) has released the <strong>admit card for the Central Teacher Eligibility Test (CTET) July 2026</strong> on its official website ctet.nic.in. The CTET is a national-level eligibility test that determines the eligibility of candidates for appointment as teachers for Classes I to VIII in central government schools such as Kendriya Vidyalayas, Navodaya Vidyalayas and other schools under the administrative control of the Government of India. Many state governments and private schools also accept the CTET qualification.</p><h3>About the Examination</h3><p>The CTET is conducted in two papers. Paper-I is for candidates intending to teach Classes I to V (Primary stage), while Paper-II is for those intending to teach Classes VI to VIII (Elementary stage). Candidates who wish to teach across both levels can appear for both papers. The qualification is valid for a lifetime, and there is no restriction on the number of attempts a candidate can make to improve their score.</p><h3>How to Download the Admit Card</h3><ol><li>Visit the official CTET website ctet.nic.in.</li><li>Click on the CTET July 2026 Admit Card download link.</li><li>Enter your Application Number and Date of Birth or password.</li><li>The admit card will be displayed with your photograph, exam centre, date, shift and reporting time.</li><li>Download and take a clear printout on A4 size paper for use on the examination day.</li></ol><h3>Documents to Carry</h3><p>Candidates must carry the printed admit card along with one original valid photo identity proof such as Aadhaar Card, Voter ID, PAN Card, Driving Licence or Passport. A passport-size photograph identical to the one uploaded during registration must be affixed in the designated space on the admit card. Candidates without the admit card and valid identity proof will not be allowed to enter the examination hall.</p><h3>Important Instructions</h3><p>Candidates should report to the examination centre at the reporting time mentioned on the admit card, which is well before the gate closing time. Electronic items such as mobile phones, calculators, smartwatches, Bluetooth devices, and study material are strictly prohibited inside the examination hall. Candidates must verify all details printed on the admit card and immediately contact the CBSE helpline in case of any discrepancy in name, photograph, category or examination details.</p><h3>Examination Pattern</h3><p>Each CTET paper consists of 150 multiple choice questions for 150 marks to be answered in 150 minutes. Paper-I covers Child Development and Pedagogy, Language I, Language II, Mathematics and Environmental Studies. Paper-II covers Child Development and Pedagogy, Language I, Language II, and either Mathematics &amp; Science or Social Studies/Social Science depending on the candidate''s subject. There is no negative marking in the CTET examination.</p><h3>Qualifying Criteria</h3><p>To qualify the CTET, a candidate must secure at least 60 percent marks, that is, 90 marks out of 150. Relaxation in qualifying marks is provided to SC, ST, OBC and Persons with Disabilities as per the policy of the respective government or recruiting authority. Qualified candidates are issued an eligibility certificate, which is a mandatory requirement for applying to teaching posts in the schools that recognise the CTET.</p>', 'Teaching', 'CBSE', 'Central Board of Secondary Education', 'admitcard', '2026-04-01', '2026-07-01', NULL, NULL, NULL, '2026-07-12', '2026-07-08', NULL, '2026-06-19 10:00:00', NULL, 'No specific upper age limit (minimum 17-18 years as per teacher training course)', 'Senior Secondary with 50% and Diploma/Degree in Elementary Education (D.El.Ed/B.El.Ed) or B.Ed as applicable for the relevant paper.', 'Candidates must possess the prescribed teacher training qualification (D.El.Ed/B.El.Ed/B.Ed) along with the required academic percentage to be eligible for the relevant CTET paper.', 1000.00, 1000.00, 500.00, 'https://ctet.nic.in', 'https://ctet.nic.in', 'https://ctet.nic.in/notifications/ctet-july-2026.pdf', 'https://ctet.nic.in/admit-card', NULL, NULL, 'admitcard', 'ADMIT_CARD', 0, 1, 'CTET July 2026 Admit Card – Download Hall Ticket at ctet.nic.in', 'CTET July 2026 admit card released by CBSE. Download hall ticket at ctet.nic.in using application number and date of birth. Check exam pattern and instructions.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'UGC NET June 2026 Admit Card – Download NTA Hall Ticket Online', 'ugc-net-june-2026-admit-card', 'National Testing Agency has released the UGC NET June 2026 admit card for the National Eligibility Test for Assistant Professor and Junior Research Fellowship. Candidates can download the hall ticket from ugcnet.nta.ac.in using their application number and date of birth.', '<h2>UGC NET June 2026 Admit Card</h2><p>The National Testing Agency (NTA) has released the <strong>admit card for the UGC NET June 2026</strong> examination on its official website ugcnet.nta.ac.in. The University Grants Commission National Eligibility Test (UGC NET) is conducted to determine the eligibility of Indian nationals for the post of Assistant Professor and for the award of Junior Research Fellowship (JRF) and admission to PhD programmes in Indian universities and colleges. Candidates who registered for the examination can now download their admit card, which is a mandatory document for entry into the examination centre.</p><h3>About the Examination</h3><p>UGC NET is a computer based test conducted in numerous subjects covering humanities, social sciences, sciences, commerce, languages and other disciplines. The examination consists of two papers conducted in a single session. Paper-I is common to all candidates and assesses teaching and research aptitude, while Paper-II is based on the specific subject chosen by the candidate. The qualification opens up academic and research career opportunities in universities and colleges across the country.</p><h3>Exam City Intimation Slip</h3><p>Before releasing the admit card, NTA publishes the Advance City Intimation Slip, which informs candidates of the city allotted for their examination. This enables candidates to make travel and accommodation arrangements in advance. The city slip should not be confused with the admit card; the actual admit card containing the full centre address and reporting details is released closer to the examination date.</p><h3>How to Download the Admit Card</h3><ol><li>Visit the official UGC NET website ugcnet.nta.ac.in.</li><li>Click on the UGC NET June 2026 Admit Card download link.</li><li>Enter your Application Number, Date of Birth and security pin.</li><li>The admit card will be displayed with your photograph, exam centre, date, shift and subject.</li><li>Download and print the admit card on A4 size paper and read all instructions carefully.</li></ol><h3>Documents to Carry</h3><p>Candidates must carry the printed admit card with a passport-size photograph affixed in the designated space, along with a valid original photo identity proof such as Aadhaar Card, PAN Card, Voter ID, Passport or Driving Licence. PwD candidates availing a scribe must carry the relevant certificate as per the guidelines. Candidates failing to produce the required documents will not be permitted to appear in the examination.</p><h3>Important Instructions</h3><p>Candidates should reach the examination centre well before the reporting time mentioned on the admit card, as late entry is not allowed. Mobile phones, calculators, electronic gadgets, smartwatches, and any printed or written material are strictly prohibited inside the examination hall. Candidates must verify all details on the admit card and contact the NTA helpline in case of any discrepancy.</p><h3>Examination Pattern</h3><p>The UGC NET examination consists of two papers with a total of 150 questions for 300 marks, conducted in a single three-hour session without any break. Paper-I contains 50 questions for 100 marks, and Paper-II contains 100 questions for 200 marks. Each correct answer carries 2 marks, and there is no negative marking. The medium of the question paper is both English and Hindi for most subjects.</p>', 'Teaching', 'NTA', 'National Testing Agency', 'admitcard', '2026-04-15', '2026-06-15', NULL, NULL, NULL, '2026-06-22', '2026-06-18', NULL, '2026-06-19 10:00:00', NULL, 'No upper age limit for Assistant Professor; below 31 years for JRF (with relaxation)', 'Master''s Degree with at least 55% marks (50% for reserved categories) from a recognized University in the relevant subject.', 'Candidates must hold a Master''s Degree with the prescribed minimum percentage. The admit card is mandatory for entry to the examination centre.', 1150.00, 600.00, 325.00, 'https://ugcnet.nta.ac.in', 'https://nta.ac.in', 'https://ugcnet.nta.ac.in/notifications/ugc-net-june-2026.pdf', 'https://ugcnet.nta.ac.in/admit-card', NULL, NULL, 'admitcard', 'ADMIT_CARD', 0, 1, 'UGC NET June 2026 Admit Card – Download Hall Ticket at NTA', 'UGC NET June 2026 admit card released by NTA. Download hall ticket at ugcnet.nta.ac.in using application number and date of birth. Check exam pattern.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'SSC CHSL 2026 Tier-I Answer Key – Download Response Sheet & Objection', 'ssc-chsl-2026-tier-1-answer-key', 'Staff Selection Commission has released the SSC CHSL 2026 Tier-I tentative answer key. Candidates can download their response sheet and the question paper, and submit objections online at ssc.gov.in by paying Rs. 100 per question challenged within the prescribed window.', '<h2>SSC CHSL 2026 Tier-I Answer Key</h2><p>The Staff Selection Commission (SSC) has released the <strong>tentative answer key for the Combined Higher Secondary Level (CHSL) Tier-I Examination 2026</strong> on its official website ssc.gov.in. Along with the answer key, the Commission has uploaded the question paper and the candidate''s recorded responses. This facility enables every candidate who appeared in the Tier-I Computer Based Examination to verify their marked answers against the answers considered correct by the Commission and to estimate their probable score before the result is declared.</p><h3>About the Answer Key Facility</h3><p>The tentative answer key is accessible through the candidate login on the SSC portal. Each question is displayed along with the four options, the option marked by the candidate, and the option treated as correct. This transparent process allows candidates to identify questions where they may have a valid disagreement with the official key and to raise objections accordingly. The facility remains open for a limited number of days, usually three to four days.</p><h3>How to Download the Answer Key</h3><ol><li>Visit the official SSC website ssc.gov.in.</li><li>Click on the link for CHSL 2026 Tier-I Answer Key/Response Sheet.</li><li>Log in using your Roll Number and Password or registration details.</li><li>View and download your question paper, marked responses and the tentative answer key.</li><li>Save the document for score calculation and to prepare objections if required.</li></ol><h3>How to Raise Objections</h3><p>Candidates who wish to challenge any answer can do so online during the objection window by paying a non-refundable fee of Rs. 100 per question or answer challenged. This fee is refunded if the objection is found valid after review by the Commission''s expert committee. Candidates must provide proper justification and authentic references for each objection. Representations received after the deadline or through any mode other than the online portal will not be considered.</p><h3>Importance of the Answer Key</h3><p>The answer key is important because the final result of the Tier-I examination is prepared on the basis of the final answer key, which is published after evaluating all objections received from candidates. By comparing their responses with the tentative key, candidates can accurately estimate their score using the marking scheme of two marks for each correct answer and a deduction of 0.50 mark for each incorrect answer, helping them assess their chances of qualifying for Tier-II.</p><h3>Tier-I Exam Pattern Recap</h3><p>The SSC CHSL Tier-I examination is an online objective test of 200 marks consisting of 100 questions to be answered in 60 minutes. The four sections are General Intelligence, General Awareness, Quantitative Aptitude and English Language, each carrying 50 marks. Each correct answer is awarded 2 marks, and 0.50 mark is deducted for every wrong answer.</p><h3>After the Objection Window</h3><p>Once the objection window closes, the Commission''s subject experts review all the objections submitted by candidates. Based on their findings, a final answer key is prepared, and the Tier-I result is declared accordingly. Candidates who qualify Tier-I as per the category-wise cut off become eligible to appear in the Tier-II examination, after which the final merit and post allocation are determined.</p>', 'Central Govt', 'SSC', 'Staff Selection Commission', 'notification', '2026-04-12', '2026-04-13', NULL, NULL, NULL, '2026-04-10', NULL, NULL, '2026-06-19 10:00:00', 7500, '18-27 Years (5 years for SC/ST, 3 for OBC)', '12th Standard (10+2) Pass from a recognized Board or equivalent.', 'Candidates who appeared in CHSL Tier-I can review the answer key and raise objections at Rs. 100 per question. Final result is based on the revised final answer key.', 100.00, 100.00, 0.00, 'https://ssc.gov.in', 'https://ssc.gov.in', 'https://ssc.gov.in/answer-key/chsl-2026-tier1.pdf', 'https://ssc.gov.in/answer-key', NULL, NULL, 'active', 'ANSWER_KEY', 0, 1, 'SSC CHSL 2026 Tier-I Answer Key – Response Sheet & Objection Link', 'SSC CHSL 2026 Tier-I answer key released at ssc.gov.in. Download response sheet and raise objections at Rs 100 per question within the objection window.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'Indian Coast Guard Navik GD & DB 2026 – Yantrik Recruitment', 'indian-coast-guard-navik-yantrik-2026-recruitment', 'Indian Coast Guard has released the Navik (General Duty), Navik (Domestic Branch) and Yantrik 2026 recruitment notification. Eligible male candidates can apply online at joinindiancoastguard.cdac.in. Selection is through a computer based stage test, physical fitness test and medical examination.', '<h2>Indian Coast Guard Navik & Yantrik 2026 Recruitment</h2><p>The Indian Coast Guard (ICG), an armed force under the Ministry of Defence, has released the official notification for recruitment to the posts of <strong>Navik (General Duty), Navik (Domestic Branch) and Yantrik</strong> for the year 2026. The Indian Coast Guard is responsible for the protection of India''s maritime interests, enforcement of maritime law, search and rescue operations, and protection of the marine environment. A career in the Coast Guard offers adventure, prestige, attractive pay and the honour of serving the nation along its vast coastline.</p><h3>About the Posts</h3><p>Navik (General Duty) personnel are engaged in general operations and navigation duties on board ships, while Navik (Domestic Branch) personnel handle cooking, catering and housekeeping functions. Yantriks are technically qualified personnel responsible for the operation and maintenance of machinery and equipment. These posts fall under the appropriate pay levels with sea-going allowance, dearness allowance and other benefits, along with excellent opportunities for promotion and career advancement within the force.</p><h3>Important Dates</h3><ul><li>Notification Release Date: 5 June 2026</li><li>Online Application Start Date: 10 June 2026</li><li>Last Date to Apply Online: 25 June 2026</li><li>Stage-I Computer Based Examination: August 2026 (Tentative)</li></ul><h3>Eligibility & Educational Qualification</h3><p>For Navik (General Duty), candidates must have passed <strong>Class 12 (10+2)</strong> with Mathematics and Physics from a recognized Board. For Navik (Domestic Branch), candidates must have passed Class 10 (Matriculation) from a recognized Board. For Yantrik, candidates must have passed Class 10 along with a Diploma in Electrical, Mechanical, Electronics or Telecommunication (Radio/Power) Engineering from a recognized institution, or Class 10 with the relevant diploma as specified. All qualifications must be from boards or institutions recognised by the appropriate authority.</p><h3>Age Limit</h3><p>The age limit for these posts is generally between 18 and 22 years as on the cut-off date specified in the notification. Age relaxation is provided to SC, ST and OBC candidates as per government norms. The recruitment is open to male candidates who meet the prescribed eligibility and physical standards.</p><h3>Physical Standards</h3><p>Candidates must meet the prescribed physical standards, including a minimum height of 157 cm, with proportionate weight and chest measurement allowing a minimum expansion of 5 cm. Candidates must have good eyesight as per the standards laid down for each branch, and must be free from any disease or disability that would interfere with the efficient performance of duties. A Physical Fitness Test involving a timed run, push-ups and sit-ups is part of the selection.</p><h3>Selection Process</h3><p>The selection process consists of a Stage-I Computer Based Examination covering subjects relevant to the post such as Mathematics, Science, English, Reasoning and General Knowledge. Candidates who qualify Stage-I proceed to the Physical Fitness Test, document verification and a recruitment medical examination. The final selection and merit are based on performance in the written examination, subject to clearing the physical and medical standards.</p><h3>How to Apply</h3><p>Eligible candidates must visit the official website joinindiancoastguard.cdac.in, register with valid details, fill the online application form, upload the scanned photograph, signature and required documents, pay the application fee where applicable, and submit the form before the last date. Candidates should keep a printout of the submitted application for future reference.</p>', 'Defence', 'Indian Coast Guard', 'Indian Coast Guard', 'notification', '2026-06-05', '2026-06-06', '2026-06-10', '2026-06-25', '2026-06-25', '2026-08-10', NULL, NULL, '2026-06-19 10:00:00', 320, '18-22 Years (relaxation for SC/ST/OBC as per norms)', 'Navik GD: 12th with Maths and Physics. Navik DB: 10th pass. Yantrik: 10th with Diploma in Electrical/Mechanical/Electronics/Telecommunication Engineering.', 'Educational qualification varies by post. Candidates must clear the Computer Based Examination, Physical Fitness Test and recruitment medical examination.', 300.00, 300.00, 0.00, 'https://joinindiancoastguard.cdac.in', 'https://indiancoastguard.gov.in', 'https://joinindiancoastguard.cdac.in/notifications/navik-yantrik-2026.pdf', 'https://joinindiancoastguard.cdac.in', NULL, NULL, 'active', 'ACTIVE', 0, 1, 'Indian Coast Guard Navik Yantrik 2026 – Apply Online', 'Indian Coast Guard Navik GD, DB and Yantrik 2026 recruitment. Apply online at joinindiancoastguard.cdac.in before 25 June 2026. Check eligibility and physical standards.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'UPPSC PCS Prelims 2026 Admit Card – Download e-Admit Card Online', 'uppsc-pcs-prelims-2026-admit-card', 'Uttar Pradesh Public Service Commission has released the PCS Preliminary Examination 2026 admit card. Candidates can download their e-admit card from uppsc.up.nic.in using their registration number and date of birth. The Combined State/Upper Subordinate Services Prelims is scheduled accordingly.', '<h2>UPPSC PCS Prelims 2026 Admit Card</h2><p>The Uttar Pradesh Public Service Commission (UPPSC) has released the <strong>admit card for the Combined State / Upper Subordinate Services (PCS) Preliminary Examination 2026</strong> on its official website uppsc.up.nic.in. The PCS examination is conducted to recruit candidates for various administrative, police and allied services posts under the Government of Uttar Pradesh, including Deputy Collector, Deputy Superintendent of Police, Block Development Officer and other Group A and Group B posts. Candidates who applied for the examination can now download their e-admit card, which is mandatory for entry into the examination centre.</p><h3>About the Examination</h3><p>The UPPSC PCS examination is one of the most competitive state civil services examinations in the country. It is conducted in three stages: the Preliminary Examination, the Main Examination and the Interview. The Preliminary Examination is a screening test, and only candidates who qualify it are allowed to appear in the Main Examination. The posts offer significant administrative responsibility, social prestige and excellent career growth within the state government.</p><h3>How to Download the Admit Card</h3><ol><li>Visit the official UPPSC website uppsc.up.nic.in.</li><li>Click on the PCS Prelims 2026 Admit Card download link.</li><li>Log in using your Registration Number, Date of Birth and password.</li><li>The admit card will be displayed with your photograph, exam centre, date, shift and reporting time.</li><li>Download and take a clear printout on A4 size paper for use on the examination day.</li></ol><h3>Documents to Carry</h3><p>Candidates must carry the printed admit card along with one original valid photo identity proof such as Aadhaar Card, Voter ID, PAN Card, Driving Licence or Passport. A passport-size photograph identical to the one uploaded during registration should also be carried. Candidates who fail to produce the admit card and valid identity proof will not be permitted to enter the examination hall under any circumstances.</p><h3>Important Instructions</h3><p>Candidates are advised to reach the examination centre at least one hour before the reporting time mentioned on the admit card, as late entry is strictly not permitted. Electronic items such as mobile phones, calculators, smartwatches, Bluetooth devices and study material are prohibited inside the examination hall. Candidates must verify all details printed on the admit card and report any discrepancy in name, photograph, category or examination details to the Commission immediately.</p><h3>Examination Pattern</h3><p>The UPPSC PCS Preliminary Examination consists of two papers, each of 200 marks. General Studies Paper-I covers current events, history, geography, Indian polity, economy, environment and general science. General Studies Paper-II (CSAT) covers comprehension, interpersonal skills, logical reasoning, analytical ability, decision making, problem solving and basic numeracy, and is qualifying in nature with a minimum requirement of 33 percent. The marks of Paper-I determine the cut off for the Main Examination.</p><h3>After the Examination</h3><p>Candidates who qualify the Preliminary Examination must prepare for the Main Examination, which is a descriptive written test followed by an interview. Candidates should retain their admit card carefully, as it may be required at subsequent stages of the recruitment and for any future correspondence with the Commission. It is also advisable to keep multiple printouts of the admit card and to preserve the registration details safely until the entire recruitment process is completed.</p>', 'State Govt', 'UPPSC', 'Uttar Pradesh Public Service Commission', 'admitcard', '2026-05-01', '2026-06-10', NULL, NULL, NULL, '2026-06-21', '2026-06-12', NULL, '2026-06-19 10:00:00', 220, '21-40 Years (relaxation as per UP government rules)', 'Bachelor''s Degree in any discipline from a recognized University or equivalent.', 'Graduate candidates who applied for the PCS examination can download the prelims admit card. Qualifying the prelims is mandatory to appear in the Main Examination.', 125.00, 125.00, 65.00, 'https://uppsc.up.nic.in', 'https://uppsc.up.nic.in', 'https://uppsc.up.nic.in/notifications/pcs-prelims-2026.pdf', 'https://uppsc.up.nic.in/admit-card', NULL, NULL, 'admitcard', 'ADMIT_CARD', 0, 1, 'UPPSC PCS Prelims 2026 Admit Card – Download at uppsc.up.nic.in', 'UPPSC PCS Preliminary 2026 admit card released. Download e-admit card at uppsc.up.nic.in using registration number and date of birth. Check exam pattern.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(NULL, 'RRB ALP 2026 CBT-1 Result – Check Scorecard, Cut Off & CBT-2 Shortlist', 'rrb-alp-2026-cbt-1-result', 'Railway Recruitment Boards have declared the Assistant Loco Pilot (ALP) 2026 CBT-1 result. Candidates who appeared in the First Stage Computer Based Test can check their qualifying status, normalised marks and category-wise cut off at rrbcdg.gov.in to proceed to CBT-2.', '<h2>RRB ALP 2026 CBT-1 Result</h2><p>The Railway Recruitment Boards (RRBs) have declared the <strong>First Stage Computer Based Test (CBT-1) result for the Assistant Loco Pilot (ALP) 2026</strong> recruitment. The CBT-1 examination was conducted to screen candidates for the technically demanding and safety-critical post of Assistant Loco Pilot in Indian Railways. Candidates who appeared in the examination can now check their qualifying status, normalised marks and category-wise cut off on the official regional RRB websites as well as the central portal rrbcdg.gov.in.</p><h3>About the Recruitment</h3><p>The Assistant Loco Pilot is one of the most prestigious technical posts in Indian Railways, responsible for assisting the Loco Pilot in operating trains. The post falls under Pay Level 2 with running allowance and other railway benefits. Candidates who clear CBT-1 are shortlisted for the Second Stage CBT (CBT-2) in a ratio of fifteen times the number of vacancies, based on their normalised marks and category.</p><h3>How to Check the Result</h3><ol><li>Visit the official regional RRB website or rrbcdg.gov.in.</li><li>Click on the link for ALP 2026 CBT-1 Result.</li><li>A PDF containing the roll numbers of shortlisted candidates will open.</li><li>Search for your roll number using Ctrl+F.</li><li>Log in with your Registration Number and Date of Birth to view your individual scorecard with normalised marks.</li></ol><h3>Scorecard and Cut Off</h3><p>The individual scorecard displays the candidate''s name, roll number, registration number, category, raw marks, normalised marks and qualifying status. The minimum qualifying percentages are 40 percent for UR and EWS, 30 percent for OBC and SC, and 25 percent for ST candidates. However, the actual cut off for shortlisting to CBT-2 is generally higher and depends on the number of vacancies, the number of candidates and the difficulty level of the examination. Category-wise and RRB-wise cut off marks are published with the result.</p><h3>Next Steps for Qualified Candidates</h3><p>Candidates shortlisted in CBT-1 must prepare for the Second Stage CBT (CBT-2), which consists of two parts. Part A covers Mathematics, General Intelligence &amp; Reasoning and Basic Science &amp; Engineering, while Part B is a trade-specific qualifying test based on the candidate''s ITI trade or engineering discipline. Candidates qualifying CBT-2 proceed to the Computer Based Aptitude Test (CBAT), in which a minimum of 42 marks in each test battery is mandatory, followed by document verification and a medical examination.</p><h3>Normalisation of Marks</h3><p>Since the CBT-1 examination is conducted in multiple shifts over several days, the raw marks of candidates are normalised using the established formula to ensure fairness across sessions of varying difficulty. The normalised marks are used to determine the qualifying status and the shortlisting for the next stage.</p><h3>Important Note</h3><p>Candidates are advised to download and preserve their scorecard for future reference. The RRBs publish results only on their official websites, and candidates should beware of fake websites and fraudulent agents. Any grievance regarding the result may be addressed to the concerned RRB through the official channel within the timeframe specified in the result notice. Candidates who have qualified should immediately begin focused preparation for CBT-2 and the aptitude test, and should keep their ITI or engineering certificates, category certificate and recent photographs ready for the document verification stage that follows.</p>', 'Railways', 'RRB', 'Indian Railways', 'result', '2026-06-05', '2026-06-15', NULL, NULL, NULL, '2026-09-20', NULL, '2026-06-15', '2026-06-19 10:00:00', 18799, '18-30 Years (5 years for SC/ST, 3 for OBC)', 'Matriculation (10th) plus ITI in relevant trade, OR Diploma/Degree in relevant Engineering branch from a recognized institution.', 'Candidates qualifying CBT-1 proceed to CBT-2, the Computer Based Aptitude Test and document verification. Normalised marks determine the shortlisting.', 500.00, 500.00, 250.00, 'https://rrbcdg.gov.in', 'https://rrbcdg.gov.in', 'https://rrbcdg.gov.in/results/alp-2026-cbt1.pdf', 'https://rrbcdg.gov.in/result', NULL, NULL, 'result', 'RESULT', 0, 1, 'RRB ALP 2026 CBT-1 Result – Scorecard & Cut Off at rrbcdg.gov.in', 'RRB ALP 2026 CBT-1 result declared. Check qualifying status, normalised marks and category-wise cut off at rrbcdg.gov.in. CBT-2 shortlist released.', NULL, 0, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
